function nextQuoteNumber(){
  const nums=(db.quotes||[]).map(q=>Number(q.numero)||0);
  return Math.max(0,...nums)+1;
}
function nextOrderNumber(){
  const nums=(db.orders||[]).map(o=>Number(o.numero)||0);
  return Math.max(0,...nums)+1;
}

