function fillSelect(el,items,selected){el.innerHTML=items.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function stockOptions(type){return (db.products||[]).filter(p=>p.stockManaged&&canonicalProductType(p.type)===canonicalProductType(type)&&Number(p.qty||0)>0)}
function uniqueSorted(a){return [...new Set(a.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'pt-BR'))}
function setSelectOptions(el,items,preferred){if(!el)return;const old=preferred??el.value;const vals=uniqueSorted(items);el.innerHTML=vals.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if(vals.includes(old))el.value=old;else if(vals.length)el.value=vals[0]}
// V11: catálogo oficial do orçamento vem de price_products. A baixa de estoque continua separada nesta etapa.
function officialQuoteProducts(category){return (priceProducts||[]).filter(p=>Number(p.active??1)===1&&norm(p.category)===norm(category))}
function quoteFabricName(p){
  let n=norm(p?.product_name||'');
  if(n==='LINHO 300 CM SINTÉTICO'||n==='LINHO SINTÉTICO WIDE 330 CM')return 'LINHO SINTÉTICO';
  if(n==='LINHO 300CM COMPOSTO 6%'||n==='LINHO 6% WIDE 330 CM')return 'LINHO COMPOSTO 6%';
  if(n==='FORRO LEVE'||n==='FORRO LEVE WIDE 330')return 'FORRO LEVE';
  // Agrupa variações do mesmo tecido por largura (ex.: BLACKOUT 280/320 CM).
  return n.replace(/\s+WIDE\b/g,'').replace(/\s+\d{3}\s*CM\b/g,'').replace(/\s+/g,' ').trim();
}
function officialFabricWidthCm(p){
  const w=Number(p?.width_cm||0);if(w>0)return w;
  const n=norm(p?.product_name||'');const m=n.match(/(\d{3})\s*CM/);if(m)return Number(m[1]);
  if(n.includes('WIDE')&&n.includes('330'))return 330;
  return 300;
}
function resolveOfficialFabric(category,name,color,heightCm){
  const list=officialQuoteProducts(category).filter(p=>quoteFabricName(p)===norm(name)&&norm(p.color)===norm(color));
  if(!list.length)return null;
  const required=Number(heightCm||0)+25;
  const ordered=[...list].sort((a,b)=>officialFabricWidthCm(a)-officialFabricWidthCm(b));
  return ordered.find(p=>officialFabricWidthCm(p)>=required)||ordered[ordered.length-1]||null;
}
function refreshFinishColors(){const name=$('eFinish')?.value;setSelectOptions($('eFinishColor'),officialQuoteProducts('TECIDO DE ACABAMENTO').filter(p=>quoteFabricName(p)===norm(name)).map(p=>p.color),$('eFinishColor')?.value)}
function refreshLiningColors(){const name=$('eLining')?.value;setSelectOptions($('eLiningColor'),officialQuoteProducts('TECIDO DE FORRO').filter(p=>quoteFabricName(p)===norm(name)).map(p=>p.color),$('eLiningColor')?.value)}
function fixationColors(kind){
  if(kind==='TRILHO SUÍÇO'){
    const rail=stockOptions('ACESSÓRIOS').filter(p=>stockName(p.name)==='TRILHO SUÍÇO').map(p=>norm(p.color));
    const claws=stockOptions('AVIAMENTO').filter(p=>stockName(p.name)==='GARRAS DE TRILHO').map(p=>norm(p.color));
    const ends=stockOptions('ACESSÓRIOS').filter(p=>stockName(p.name)==='ACABAMENTO TRILHO SUÍÇO').map(p=>norm(p.color));
    return rail.filter(c=>claws.includes(c)&&ends.includes(c));
  }
  if(String(kind||'').startsWith('VARÃO WAVE')){
    const rod=stockOptions('ACESSÓRIOS').filter(p=>stockName(p.name)==='VARÃO WAVE 28').map(p=>norm(p.color));
    const sup=stockOptions('ACESSÓRIOS').filter(p=>stockName(p.name)==='SUPORTE WAVE 28').map(p=>norm(p.color));
    const cap=stockOptions('ACESSÓRIOS').filter(p=>stockName(p.name)==='TAMPA VARÃO WAVE 28').map(p=>norm(p.color));
    return rod.filter(c=>sup.includes(c)&&cap.includes(c));
  }
  return [];
}
function refreshFixColors(){setSelectOptions($('eFixColor'),fixationColors($('eFixation')?.value),$('eFixColor')?.value)}
function setupSelectors(){
  setSelectOptions($('eFinish'),officialQuoteProducts('TECIDO DE ACABAMENTO').map(quoteFabricName),$('eFinish')?.value);refreshFinishColors();
  setSelectOptions($('eLining'),officialQuoteProducts('TECIDO DE FORRO').map(quoteFabricName),$('eLining')?.value);refreshLiningColors();
  fillSelect($('eFinishPleat'),['FRANZIDO','WAVE','SOBREPOSTO','OUTRO'],'WAVE');fillSelect($('eLiningPleat'),['FRANZIDO','WAVE','SOBREPOSTO','OUTRO'],'FRANZIDO');fillSelect($('eFinishGather'),['1.5','2.0','2.5','3.0','3.5','4.0'],'3.0');fillSelect($('eLiningGather'),['1.5','2.0','2.5','3.0','3.5','4.0'],'2.0');
  const fix=[];if(fixationColors('TRILHO SUÍÇO').length)fix.push('TRILHO SUÍÇO');if(fixationColors('VARÃO WAVE').length){fix.push('VARÃO WAVE','VARÃO WAVE COM COMANDO POR CORDA')}setSelectOptions($('eFixation'),fix,$('eFixation')?.value);refreshFixColors();updateModelFields();
}
function updateModelFields(){const m=$('eModel').value;document.querySelectorAll('.finish-field').forEach(x=>x.classList.toggle('hidden',m==='LINING'));document.querySelectorAll('.lining-field').forEach(x=>x.classList.toggle('hidden',m==='FINISH'));document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('active',x.dataset.model===m));updatePreview()}
function fabricCalc(type,name,widthM,heightM,gather,productId,color){const category=type==='finish'?'TECIDO DE ACABAMENTO':'TECIDO DE FORRO';const hCm=heightM*100;let sku=(priceProducts||[]).find(p=>Number(p.id)===Number(productId));if(!sku)sku=resolveOfficialFabric(category,name,color,hCm);if(!sku)return null;const gathered=widthM*Number(gather);const fabricWidth=officialFabricWidthCm(sku);let mode='LARGURA',panels=0,cutLength=0,consumption=gathered;if(hCm+25>fabricWidth){mode='ALTURA';cutLength=heightM+0.10+(heightM*0.10);panels=Math.ceil(gathered/(fabricWidth/100));consumption=panels*cutLength}const unitPrice=Number(sku.price_4x||0);return {name,gathered,mode,panels,cutLength,consumption,unitPrice,pricePct:0,cost:consumption*unitPrice,productId:sku.id,internalCode:sku.internal_code,officialName:sku.product_name,fabricWidthCm:fabricWidth}}
function fixationCalc(kind,widthM,model,leaves){const c=db.priceConfig;if(kind==='TRILHO SUÍÇO'){const rounded=Math.max(1.5,Math.ceil(widthM*2)/2);const tier=(c.swiss.tiers||[]).find(t=>rounded<=Number(t.m))||c.swiss.tiers[c.swiss.tiers.length-1];const clamps=Math.ceil(rounded/0.5);const ends=2;const base=Number(tier?.p||0)+clamps*Number(c.swiss.clamp||0)+ends*Number(c.swiss.end||0);return {kind,meters:rounded,clamps,ends,hardwareBase:base,total:base,detail:`${rounded.toFixed(1)}m • ${clamps} garras • ${ends} acabamentos`}}
  const multiplier=model==='COMPLETE'?2:1;const rodMeters=widthM*multiplier;const supports=widthM<=2.30?2:widthM<4?3:widthM<5?4:widthM<=6?5:Math.max(5,Math.ceil(widthM));const ends=model==='COMPLETE'?4:2;const supportName=model==='COMPLETE'?'SUPORTE DUPLO':'SUPORTE SIMPLES';const supportSku=(priceProducts||[]).find(p=>Number(p.active??1)===1&&norm(p.category)==='ACESSÓRIO'&&norm(p.product_name)===supportName&&norm(p.color)===norm(arguments[4]||''));const supportUnit=supportSku?Number(supportSku.price_4x||0):Number(c.wave.support||0);const base=rodMeters*Number(c.wave.rodPerMeter||0)+supports*supportUnit+ends*Number(c.wave.end||0);let total=base;if(kind.includes('COMANDO'))total=base*(1+Number(c.cordPct||0)/100);if(kind==='TRILHO MOTORIZADO')total=base*(1+Number(c.motor.hardwarePct||0)/100)+Number(c.motor.basePerLeaf||0)*Number(leaves||1);return {kind,meters:rodMeters,supports,ends,supportName,supportProductId:supportSku?.id||null,supportInternalCode:supportSku?.internal_code||'',hardwareBase:base,total,detail:`${rodMeters.toFixed(2)}m • ${supports} ${supportName.toLowerCase()} • ${ends} tampas`}}
function installPrice(heightM){const tier=(db.priceConfig.install||[]).find(x=>heightM<=Number(x.maxH));return Number(tier?.price||0)}
function calcEnvironment(e){const w=Number(e.width)/100,h=Number(e.height)/100,leaves=Number(e.leaves||1);if(!w||!h)return null;const finish=e.model!=='LINING'?fabricCalc('finish',e.finish,w,h,e.finishGather,e.finishProductId,e.finishColor):null;const lining=e.model!=='FINISH'?fabricCalc('lining',e.lining,w,h,e.liningGather,e.liningProductId,e.liningColor):null;const layers=[finish,lining].filter(Boolean).length;const lateral=h*2*leaves*layers;const bars=(finish?.gathered||0)+(lining?.gathered||0);const sewingMeters=lateral+bars;const sewingCost=sewingMeters*Number(db.priceConfig.sewingPerMeter||0);const finishPleat=finish?finish.consumption*Number(db.priceConfig.pleatLabor[e.finishPleat]||0):0;const liningPleat=lining?lining.consumption*Number(db.priceConfig.pleatLabor[e.liningPleat]||0):0;const customPleat=Number(e.customPleat||0);const sliderQtyPerLayer=Math.ceil(Number(e.width)/Number(db.priceConfig.sliders.spacingCm||5));const finishSliders=finish?sliderQtyPerLayer:0,liningSliders=lining?sliderQtyPerLayer:0;const sliderCost=finishSliders*Number(db.priceConfig.sliders.finish||0)+liningSliders*Number(db.priceConfig.sliders.lining||0);const fixation=fixationCalc(e.fixation,w,e.model,leaves,e.fixColor);const install=installPrice(h);const laborTotal=sewingCost+finishPleat+liningPleat+customPleat+install;const base4=(finish?.cost||0)+(lining?.cost||0)+sliderCost+fixation.total+laborTotal;const p18=base4*(1+Number(db.priceConfig.terms.p18AddPct||0)/100);const cash=base4*(1-Number(db.priceConfig.terms.cashDiscountPct||0)/100);return {...e,finishCalc:finish,liningCalc:lining,lateral,bars,sewingMeters,sewingCost,finishPleat,liningPleat,sliderQtyPerLayer,finishSliders,liningSliders,sliderCost,fixationCalc:fixation,installCost:install,laborTotal,base4,p18,cash,alerts:[finish?.mode==='ALTURA'?'ACABAMENTO POR ALTURA':'',lining?.mode==='ALTURA'?'FORRO POR ALTURA':'',finish?.pricePct?`LINHO SINTÉTICO +${finish.pricePct}%`:'' ].filter(Boolean)}}
function envFromForm(){const height=Number($('eHeight').value),finish=$('eFinish').value,finishColor=$('eFinishColor').value,lining=$('eLining').value,liningColor=$('eLiningColor').value;const finishSku=resolveOfficialFabric('TECIDO DE ACABAMENTO',finish,finishColor,height),liningSku=resolveOfficialFabric('TECIDO DE FORRO',lining,liningColor,height);return {id:uid(),name:$('eName').value.trim(),width:Number($('eWidth').value),height,leaves:Number($('eLeaves').value),model:$('eModel').value,finish,finishColor,finishProductId:finishSku?.id||null,finishInternalCode:finishSku?.internal_code||'',finishOfficialName:finishSku?.product_name||'',lining,liningColor,liningProductId:liningSku?.id||null,liningInternalCode:liningSku?.internal_code||'',liningOfficialName:liningSku?.product_name||'',finishPleat:$('eFinishPleat').value,finishGather:$('eFinishGather').value,liningPleat:$('eLiningPleat').value,liningGather:$('eLiningGather').value,fixation:$('eFixation').value,fixColor:$('eFixColor').value,customPleat:Number($('eCustomPleat').value||0),notes:$('eNotes').value.trim()}}
function updatePreview(){const e=envFromForm();if(!e.name||!e.width||!e.height){$('calcPreview').innerHTML='Preencha ambiente, medidas e configuração para visualizar o cálculo.';return}const c=calcEnvironment(e);if(!c)return;const f=c.finishCalc,l=c.liningCalc;$('calcPreview').innerHTML=`<strong>${esc(e.name)}</strong>${c.alerts.length?` <span class="badge warn">${esc(c.alerts.join(' • '))}</span>`:''}<div class="detail-list"><div class="detail-item"><span>Acabamento</span><strong>${f?`${f.consumption.toFixed(2)}m • ${money(f.cost)}`:'—'}</strong></div><div class="detail-item"><span>Forro</span><strong>${l?`${l.consumption.toFixed(2)}m • ${money(l.cost)}`:'—'}</strong></div><div class="detail-item"><span>Costura</span><strong>${c.sewingMeters.toFixed(2)}m • ${money(c.sewingCost)}</strong></div><div class="detail-item"><span>Deslizantes</span><strong>${c.finishSliders+c.liningSliders} un • ${money(c.sliderCost)}</strong></div><div class="detail-item"><span>Fixação</span><strong>${money(c.fixationCalc.total)}</strong></div><div class="detail-item"><span>Mão de obra total</span><strong>${money(c.laborTotal)}</strong></div></div><div class="price-strip"><div class="price-box"><span>18x</span><strong>${money(c.p18)}</strong></div><div class="price-box"><span>4x</span><strong>${money(c.base4)}</strong></div><div class="price-box"><span>À vista</span><strong>${money(c.cash)}</strong></div><div class="price-box"><span>Fixação</span><strong>${esc(c.fixationCalc.detail)}</strong></div></div>`}
function clearEnv(){['eName','eWidth','eHeight','eNotes'].forEach(id=>$(id).value='');$('eCustomPleat').value=0;updatePreview()}

function ensureSellerControl(){const old=$('qSeller');if(!old||old.tagName==='SELECT')return;const sel=document.createElement('select');sel.id='qSeller';sel.className=old.className;old.replaceWith(sel)}
function refreshSellerControl(preferred=''){ensureSellerControl();const el=$('qSeller');if(!el)return;const active=allUsers().filter(u=>['sales','gestor'].includes(u.role));el.innerHTML=active.map(u=>`<option value="${esc(u.username)}">${esc(u.name||u.username)}</option>`).join('');const wanted=norm(preferred||draft.sellerUser||currentUser?.username);if([...el.options].some(o=>norm(o.value)===wanted))el.value=wanted;else if(el.options.length)el.selectedIndex=0;el.disabled=!isGestor();el.onchange=()=>{draft.sellerUser=norm(el.value);draft.seller=sellerName(draft.sellerUser)}}

function renderQuote(){
  refreshSellerControl(draft.sellerUser||resolveSellerUser(draft));
  $('qClient').value=draft.client||'';$('qDate').value=draft.date||today();$('qAddress').value=draft.address||'';$('qContact').value=draft.contact||'';$('qTravel').value=draft.travel||0;$('qDiscount').value=draft.discountPercent||0;$('qDiscountReason').value=draft.discountReason||'';
  const tbody=$('envTable');tbody.innerHTML='';let labor=0;
  for(const e of draft.environments||[]){const c=calcEnvironment(e);if(!c)continue;labor+=c.laborTotal;const tr=document.createElement('tr');tr.innerHTML=`<td><strong>${esc(e.name)}</strong>${c.alerts.length?`<br><span class="badge warn">${esc(c.alerts.join(' • '))}</span>`:''}</td><td>${e.width} × ${e.height} cm<br>${Math.max(0,Number(e.leaves||1)-1)} abertura(s)</td><td>${e.model==='COMPLETE'?'Cortina completa':e.model==='LINING'?'Apenas forro':'Apenas acabamento'}</td><td>${c.finishCalc?`${esc(e.finish)}<br>${esc(e.finishColor)} • ${e.finishPleat} ${e.finishGather}:1`:'—'}</td><td>${c.liningCalc?`${esc(e.lining)}<br>${esc(e.liningColor)} • ${e.liningPleat} ${e.liningGather}:1`:'—'}</td><td>${esc(e.fixation)}<br>${esc(e.fixColor)}</td><td>${money(c.laborTotal)}</td><td>${money(c.p18)}</td><td>${money(c.base4)}</td><td>${money(c.cash)}</td><td class="no-print"><button class="btn danger" data-del-env="${e.id}">Excluir</button></td>`;tbody.appendChild(tr)}
  for(const b of draft.blinds||[]){const qty=Number(b.qty||1);const tr=document.createElement('tr');tr.className='blind-row';tr.innerHTML=`<td><strong>${esc(b.environment||'PERSIANA')}</strong><br><span class="badge blue">PERSIANA</span></td><td>${b.width} × ${b.height} cm<br>${qty} un.</td><td>Persiana</td><td>${esc(b.model)}<br>${esc(b.color||'-')}</td><td>—</td><td>${esc(b.commandSide||'-')}${b.bando?`<br>Bandô: ${esc(b.bando)}`:''}</td><td>—</td><td>${money(Number(b.p18||0)*qty)}</td><td>${money(Number(b.p4||0)*qty)}</td><td>${money(Number(b.cash||0)*qty)}</td><td class="no-print"><button class="btn danger" data-del-blind="${b.id}">Excluir</button></td>`;tbody.appendChild(tr)}
  for(const a of draft.looseProducts||[]){const qty=Number(a.qty||1),tr=document.createElement('tr');tr.className='loose-row';tr.innerHTML=`<td><strong>${esc(a.description||a.name)}</strong><br><span class="badge blue">${a.stockManaged===false?'FORA DE ESTOQUE':'PRODUTO AVULSO'}</span></td><td>${qty} ${esc(a.unit||'UN')}</td><td>${esc(a.type||'')}</td><td>${esc(a.name)}<br>${esc(a.color||'')}</td><td>—</td><td>${a.priceOverride?`Preço ajustado<br><small>${esc(a.priceReason||'')}</small>`:'Preço padrão'}</td><td>—</td><td>${money(Number(a.p18||0)*qty)}</td><td>${money(Number(a.p4||0)*qty)}</td><td>${money(Number(a.cash||0)*qty)}</td><td class="no-print"><button class="btn danger" data-del-loose="${a.id}">Excluir</button></td>`;tbody.appendChild(tr)}
  const t=quoteTotals(draft);$('qCount').textContent=(draft.environments?.length||0)+(draft.blinds?.length||0)+(draft.looseProducts?.length||0);$('q18').textContent=money(t.p18);$('q4').textContent=money(t.p4);$('qCash').textContent=money(t.cash);$('sumLabor').textContent=money(labor);$('sum18').textContent=money(t.p18);$('sum4').textContent=money(t.p4);$('sumCash').textContent=money(t.cash);
  document.querySelectorAll('[data-del-env]').forEach(b=>b.onclick=()=>{draft.environments=draft.environments.filter(x=>x.id!==b.dataset.delEnv);renderQuote()});document.querySelectorAll('[data-del-blind]').forEach(b=>b.onclick=()=>{draft.blinds=(draft.blinds||[]).filter(x=>x.id!==b.dataset.delBlind);renderQuote()});document.querySelectorAll('[data-del-loose]').forEach(b=>b.onclick=()=>{draft.looseProducts=(draft.looseProducts||[]).filter(x=>x.id!==b.dataset.delLoose);renderQuote()})
}
function syncDraft(){draft.client=$('qClient').value.trim();draft.date=$('qDate').value;draft.address=$('qAddress').value.trim();draft.contact=$('qContact').value.trim();draft.sellerUser=norm($('qSeller').value||currentUser?.username);draft.seller=sellerName(draft.sellerUser);draft.travel=Number($('qTravel').value||0);draft.discountPercent=Number($('qDiscount').value||0);draft.discountReason=$('qDiscountReason').value.trim()}
function quoteTotals(q){let p18=0,p4=0,cash=0,labor=0;for(const e of q.environments||[]){const c=calcEnvironment(e);if(c){p18+=c.p18;p4+=c.base4;cash+=c.cash;labor+=c.laborTotal}}for(const b of q.blinds||[]){const qty=Number(b.qty||1);p18+=Number(b.p18||0)*qty;p4+=Number(b.p4||0)*qty;cash+=Number(b.cash||0)*qty}for(const a of q.looseProducts||[]){const qty=Number(a.qty||1);p18+=Number(a.p18||0)*qty;p4+=Number(a.p4||0)*qty;cash+=Number(a.cash||0)*qty}const t=Number(q.travel||0);p18+=t*(1+db.priceConfig.terms.p18AddPct/100);p4+=t;cash+=t*(1-db.priceConfig.terms.cashDiscountPct/100);const d=Math.max(0,Math.min(100,Number(q.discountPercent||0)));return {p18:p18*(1-d/100),p4:p4*(1-d/100),cash:cash*(1-d/100),labor,discountPercent:d}}
function saveQuote(print=false){syncDraft();if(!draft.client)return alert('Informe o cliente.');if(!draft.numero)draft.numero=nextQuoteNumber();if(!draft.environments.length&&!(draft.blinds||[]).length&&!(draft.looseProducts||[]).length)return alert('Adicione pelo menos um ambiente, persiana ou produto avulso.');if(Number(draft.discountPercent||0)>0&&!draft.discountReason)return alert('Informe a justificativa do desconto.');const existing=db.quotes.findIndex(q=>Number(q.numero)===Number(draft.numero));const q={...clone(draft),ownerUser:draft.sellerUser||currentUsername(),sellerUser:draft.sellerUser||currentUsername(),seller:sellerName(draft.sellerUser||currentUsername()),createdAt:existing>=0?db.quotes[existing].createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:db.quotes[existing]?.status||'ORÇAMENTO'};if(existing>=0)db.quotes[existing]=q;else db.quotes.unshift(q);upsertClientFromQuote(q);queueSave();renderAll();$('quoteStatus').textContent=`Orçamento ${String(q.numero).padStart(6,'0')} salvo.`;if(print)printQuote(q,'summary')}
function resetQuote(){if(!confirm('Zerar todos os dados do orçamento atual?'))return;draft={numero:null,client:'',date:today(),address:'',contact:'',seller:sellerName(currentUser?.username),sellerUser:currentUsername(),travel:0,discountPercent:0,discountReason:'',environments:[],blinds:[],looseProducts:[]};renderQuote();clearEnv()}
function upsertClientFromQuote(q){const key=norm(q.client);let c=db.clients.find(x=>norm(x.name)===key);if(c){c.address=q.address;c.contact=q.contact;c.lastSeller=q.seller;c.updatedAt=new Date().toISOString()}else db.clients.unshift({id:uid(),name:q.client,address:q.address,contact:q.contact,lastSeller:q.seller,createdAt:new Date().toISOString()})}
function printQuote(q,type='summary'){const t=quoteTotals(q),detailed=type==='detail';let rows='';for(const e of q.environments||[]){const c=calcEnvironment(e);if(!c)continue;rows+=`<tr><td><strong>${esc(e.name)}</strong>${detailed&&e.notes?`<br><small>${esc(e.notes)}</small>`:''}</td><td>${e.width} × ${e.height} cm<br>${Math.max(0,Number(e.leaves||1)-1)} abertura(s)</td><td>${esc(e.model==='COMPLETE'?'CORTINA COMPLETA':e.model==='LINING'?'APENAS FORRO':'APENAS ACABAMENTO')}</td><td>${c.finishCalc?esc(e.finish+' '+(e.finishColor||'')):'—'}</td><td>${c.liningCalc?esc(e.lining+' '+(e.liningColor||'')):'—'}</td><td>${esc(e.fixation||'-')}<br>${esc(e.fixColor||'')}</td><td>${money(c.labor)}</td><td>${money(c.p18)}</td><td>${money(c.base4)}</td><td>${money(c.cash)}</td></tr>`}for(const x of q.blinds||[]){const qty=Number(x.qty||1);rows+=`<tr><td><strong>${esc(x.environment||'PERSIANA')}</strong></td><td>${x.width} × ${x.height} cm<br>${qty} un.</td><td>PERSIANA</td><td>${esc(x.model||'-')} ${esc(x.color||'')}</td><td>—</td><td>${esc(x.commandSide||'-')}</td><td>—</td><td>${money(Number(x.p18||0)*qty)}</td><td>${money(Number(x.p4||0)*qty)}</td><td>${money(Number(x.cash||0)*qty)}</td></tr>`}if(Number(q.travel||0)>0)rows+=`<tr><td><strong>DESLOCAMENTO</strong></td><td colspan="5">Atendimento / instalação fora da praça</td><td>—</td><td>${money(Number(q.travel)*(1+db.priceConfig.terms.p18AddPct/100))}</td><td>${money(q.travel)}</td><td>${money(Number(q.travel)*(1-db.priceConfig.terms.cashDiscountPct/100))}</td></tr>`;const html=`<div class="quote-client-head"><div class="quote-brand"><img src="${location.origin}/icon-512.png"><div><h2>ORÇAMENTO Nº ${String(q.numero).padStart(6,'0')}</h2><strong>${detailed?'DETALHADO':'RESUMIDO'}</strong></div></div><div class="quote-date"><small>Data</small><div>${fmtDate(q.date)}</div></div></div><div class="section-title">▪ &nbsp; Dados do cliente</div><div class="client-grid"><div><small>Cliente</small><strong>${esc(q.client||'-')}</strong></div><div><small>Contato</small><strong>${esc(q.contact||'-')}</strong></div><div><small>Endereço</small><strong>${esc(q.address||'-')}</strong></div><div><small>Vendedor</small><strong>${esc(q.seller||'-')}</strong></div></div><div class="section-title">▪ &nbsp; Resumo do orçamento</div><table class="client-quote"><thead><tr><th>AMBIENTE</th><th>MEDIDAS</th><th>MODELO</th><th>TECIDO ACABAMENTO</th><th>FORRO</th><th>FIXAÇÃO</th><th>MÃO DE OBRA TOTAL</th><th>18X</th><th>4X</th><th>À VISTA</th></tr></thead><tbody>${rows}<tr class="total-row"><th colspan="6">TOTAL</th><th>${money((q.environments||[]).reduce((a,e)=>a+(calcEnvironment(e)?.labor||0),0))}</th><th>${money(t.p18)}</th><th>${money(t.p4)}</th><th>${money(t.cash)}</th></tr></tbody></table>${q.discountPercent?`<p><strong>Desconto aplicado:</strong> ${q.discountPercent}% • ${esc(q.discountReason||'')}</p>`:''}<div class="section-title">▪ &nbsp; Condições</div><ol class="conditions"><li>Validade do orçamento: 5 dias.</li><li>Medidas, tecidos, cores e fixações devem ser conferidos antes da ordem de produção.</li><li>Prazo padrão: até 30 dias úteis após emissão do pedido.</li></ol>`;printWindow(html)}

function renderQuotes(){const tb=$('quotesTable');if(!tb)return;const q=norm($('quoteSearch')?.value);const converted=new Set(db.orders.map(o=>Number(o.quoteNumber)));tb.innerHTML='';for(const x of db.quotes.filter(canSeeQuote).filter(x=>!q||norm(`${x.numero} ${x.client} ${displaySeller(x)}`).includes(q))){const t=quoteTotals(x),conv=converted.has(Number(x.numero));const tr=document.createElement('tr');tr.innerHTML=`<td>${String(x.numero).padStart(6,'0')}</td><td>${fmtDate(x.date)}</td><td>${esc(x.client)}</td><td>${esc(displaySeller(x))}</td><td>${(x.environments?.length||0)+(x.blinds?.length||0)+(x.looseProducts?.length||0)}</td><td>${money(t.cash)}</td><td><span class="badge ${conv?'blue':'ok'}">${conv?'PEDIDO':'ORÇAMENTO'}</span></td><td><div class="actions"><button class="btn ghost" data-q-load="${x.numero}">Abrir</button><button class="btn ghost" data-q-print="${x.numero}">PDF</button>${conv?`<button class="btn danger" data-q-revert="${x.numero}">Reverter</button>`:`<button class="btn primary" data-q-convert="${x.numero}">Converter</button>`}${isGestor()?`<button class="btn danger" data-q-delete="${x.numero}">Excluir</button>`:''}</div></td>`;tb.appendChild(tr)}bindQuoteActions()}
function bindQuoteActions(){document.querySelectorAll('[data-q-load]').forEach(b=>b.onclick=()=>{const q=db.quotes.find(x=>Number(x.numero)===Number(b.dataset.qLoad));if(q){draft=clone(q);renderQuote();setView('quote')}});document.querySelectorAll('[data-q-print]').forEach(b=>b.onclick=()=>{const q=db.quotes.find(x=>Number(x.numero)===Number(b.dataset.qPrint));if(q)openPrintChoice(q)});document.querySelectorAll('[data-q-convert]').forEach(b=>b.onclick=()=>convertQuote(Number(b.dataset.qConvert)));document.querySelectorAll('[data-q-revert]').forEach(b=>b.onclick=()=>revertQuote(Number(b.dataset.qRevert)));document.querySelectorAll('[data-q-delete]').forEach(b=>b.onclick=()=>deleteQuote(Number(b.dataset.qDelete)))}
function deleteQuote(n){if(!isGestor())return alert('Apenas o GESTOR pode excluir orçamentos.');const linked=db.orders.find(o=>Number(o.quoteNumber)===n);if(linked)return alert('Este orçamento já virou pedido. Exclua ou reverta o pedido primeiro.');if(!confirm('Excluir definitivamente este orçamento?'))return;db.quotes=db.quotes.filter(q=>Number(q.numero)!==n);queueSave();renderAll()}
function openPrintChoice(q){printQuote(q,'summary')}
function convertQuote(n){const q=db.quotes.find(x=>Number(x.numero)===n);if(!q)return;if(db.orders.some(o=>Number(o.quoteNumber)===n))return alert('Este orçamento já foi convertido em pedido.');const t=quoteTotals(q);openModal(`<h2>Converter em pedido</h2><div class="grid two"><label class="field">Condição<select id="convCond"><option value="cash">À vista</option><option value="p4">Até 4x</option><option value="p18">Até 18x</option></select></label><label class="field">Data de instalação / entrega<input id="convDate" type="date"></label><label class="field">Desconto adicional (%)<input id="convDiscount" type="number" min="0" max="100" value="0"></label><label class="field">Justificativa<input id="convReason"></label></div><p class="muted">À vista ${money(t.cash)} • 4x ${money(t.p4)} • 18x ${money(t.p18)}</p><p class="notice">A baixa do estoque acontece somente ao confirmar a geração do pedido.</p><button id="convGo" class="btn primary">Gerar pedido</button>`);$('convGo').onclick=async()=>{const cond=$('convCond').value,date=$('convDate').value,disc=Number($('convDiscount').value||0),reason=$('convReason').value.trim();if(!date)return alert('Informe a data.');if(disc>0&&!reason)return alert('Justifique o desconto.');const base=cond==='cash'?t.cash:cond==='p18'?t.p18:t.p4;const order={id:uid(),numero:nextOrderNumber(),quoteNumber:q.numero,ownerUser:q.ownerUser||currentUsername(),client:q.client,address:q.address,contact:q.contact,seller:displaySeller(q),sellerUser:resolveSellerUser(q),environments:clone(q.environments),blinds:clone(q.blinds||[]),looseProducts:clone(q.looseProducts||[]),createdDate:today(),deliveryDate:date,paymentCondition:cond,originalValue:base,discountPercent:disc,discountReason:reason,agreedValue:base*(1-disc/100),productionStage:'RECEPÇÃO',productionHistory:[{stage:'RECEPÇÃO',at:new Date().toISOString(),by:currentUsername()}],installation:{responsible:'',completedDate:''},payments:[],createdAt:new Date().toISOString()};const officialStock=await consumeOfficialStock(q,order);if(!officialStock.ok)return alert(officialStock.error);const stock=validateAndConsumeStock(q,order);if(!stock.ok){await restoreOfficialStock(order);return alert(stock.error)}db.orders.unshift(order);for(const b of q.blinds||[]){const qty=Number(b.qty||1);db.products.unshift({id:uid(),code:'PER-'+String(Date.now()).slice(-6)+'-'+Math.random().toString(36).slice(2,5).toUpperCase(),type:'PERSIANA',category:'FORNECEDOR PARCEIRO',name:b.model,color:b.color,qty,cost:Number(b.cash||0)/1.60,markup:60,unit:'UN',orderNumber:order.numero,stockManaged:false})}for(const a of q.looseProducts||[]){if(a.stockManaged===false)db.products.unshift({id:uid(),code:'ESP-'+String(Date.now()).slice(-6)+'-'+Math.random().toString(36).slice(2,5).toUpperCase(),type:a.type,category:'FORA DE ESTOQUE',name:a.name,color:a.color||'SEM COR',qty:0,cost:0,markup:0,unit:a.unit||'UN',orderNumber:order.numero,stockManaged:false,specialQty:Number(a.qty||0),specialReason:a.specialReason||'',movements:[{id:uid(),date:today(),type:'ENTRADA E SAÍDA DIRETA',qty:0,balance:0,unit:a.unit||'UN',by:currentUsername(),reason:`Pedido ${order.numero} • ${a.specialReason||'produto específico'}`} ]})}q.status='PEDIDO';queueSave();closeModal();renderAll();setView('orders')}}
async function revertQuote(n){const idx=db.orders.findIndex(o=>Number(o.quoteNumber)===n);if(idx<0)return;const order=db.orders[idx];if(!confirm(isGestor()?'Excluir o pedido vinculado e retornar o orçamento ao status ORÇAMENTO?':'Reverter este pedido para orçamento?'))return;const officialRestore=await restoreOfficialStock(order);if(!officialRestore.ok)return alert(officialRestore.error);restoreOrderStock(order);db.products=(db.products||[]).filter(p=>Number(p.orderNumber)!==Number(order.numero));db.orders.splice(idx,1);const q=db.quotes.find(x=>Number(x.numero)===n);if(q)q.status='ORÇAMENTO';queueSave();renderAll()}

function renderClients(){const tb=$('clientsTable');if(!tb)return;const s=norm($('clientSearch')?.value);tb.innerHTML='';for(const c of db.clients.filter(c=>!s||norm(`${c.name} ${c.contact} ${c.address}`).includes(s))){const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(c.name)}</td><td>${esc(c.contact||'-')}</td><td>${esc(c.address||'-')}</td><td>${esc(c.lastSeller||'-')}</td><td><button class="btn ghost" data-client-edit="${c.id}">Editar</button> <button class="btn danger" data-client-del="${c.id}">Excluir</button></td>`;tb.appendChild(tr)}document.querySelectorAll('[data-client-edit]').forEach(b=>b.onclick=()=>openClientModal(db.clients.find(c=>c.id===b.dataset.clientEdit)));document.querySelectorAll('[data-client-del]').forEach(b=>b.onclick=()=>{if(confirm('Excluir este cliente?')){db.clients=db.clients.filter(c=>c.id!==b.dataset.clientDel);queueSave();renderClients()}})}
function openClientModal(c=null){editingClientId=c?.id||null;openModal(`<h2>${c?'Editar':'Novo'} cliente</h2><div class="grid two"><label class="field">Nome<input id="mClientName" value="${esc(c?.name||'')}"></label><label class="field">Contato<input id="mClientContact" value="${esc(c?.contact||'')}"></label><label class="field" style="grid-column:1/-1">Endereço<input id="mClientAddress" value="${esc(c?.address||'')}"></label></div><button id="mClientSave" class="btn primary">Salvar</button>`);$('mClientSave').onclick=()=>{const name=$('mClientName').value.trim();if(!name)return alert('Informe o nome.');const obj={id:editingClientId||uid(),name,contact:$('mClientContact').value.trim(),address:$('mClientAddress').value.trim(),lastSeller:c?.lastSeller||sellerName(currentUser?.username),updatedAt:new Date().toISOString()};if(editingClientId){const i=db.clients.findIndex(x=>x.id===editingClientId);db.clients[i]={...db.clients[i],...obj}}else db.clients.unshift(obj);queueSave();closeModal();renderClients()}}

function renderOrders(){const tb=$('ordersTable');if(!tb)return;tb.innerHTML='';for(const o of db.orders.filter(canSeeOrder)){const install=o.installation?.completedDate?'CONCLUÍDA':o.productionStage==='EXPEDIÇÃO'?'PRONTO PARA INSTALAÇÃO':'AGUARDANDO';const tr=document.createElement('tr');tr.innerHTML=`<td>${String(o.numero).padStart(6,'0')}</td><td>${String(o.quoteNumber).padStart(6,'0')}</td><td>${esc(o.client)}</td><td>${esc(displaySeller(o))}</td><td>${money(o.agreedValue)}</td><td><span class="badge blue">${esc(o.productionStage||'RECEPÇÃO')}</span></td><td><span class="badge ${install==='CONCLUÍDA'?'ok':'warn'}">${install}</span></td><td><button class="btn ghost" data-order-open="${o.numero}">Abrir</button> ${isGestor()?`<button class="btn danger" data-order-delete="${o.numero}">Excluir</button>`:''}</td>`;tb.appendChild(tr)}document.querySelectorAll('[data-order-open]').forEach(b=>b.onclick=()=>openOrder(Number(b.dataset.orderOpen)));document.querySelectorAll('[data-order-delete]').forEach(b=>b.onclick=()=>deleteOrder(Number(b.dataset.orderDelete)))}
async function deleteOrder(n){if(!isGestor())return alert('Apenas o GESTOR pode excluir pedidos.');const o=db.orders.find(x=>Number(x.numero)===n);if(!o)return;if(!confirm('Excluir este pedido? O estoque utilizado será devolvido e o orçamento voltará ao status ORÇAMENTO.'))return;const officialRestore=await restoreOfficialStock(o);if(!officialRestore.ok)return alert(officialRestore.error);restoreOrderStock(o);db.products=(db.products||[]).filter(p=>Number(p.orderNumber)!==Number(o.numero));db.orders=db.orders.filter(x=>Number(x.numero)!==n);const q=db.quotes.find(x=>Number(x.numero)===Number(o.quoteNumber));if(q)q.status='ORÇAMENTO';queueSave();renderAll()}
function openOrder(n){const o=db.orders.find(x=>Number(x.numero)===n);if(!o)return;const paid=(o.payments||[]).reduce((a,p)=>a+Number(p.value||0),0);openModal(`<h2>Pedido ${String(o.numero).padStart(6,'0')}</h2><div class="detail-list"><div class="detail-item"><span>Cliente</span><strong>${esc(o.client)}</strong></div><div class="detail-item"><span>Valor</span><strong>${money(o.agreedValue)}</strong></div><div class="detail-item"><span>Saldo</span><strong>${money(o.agreedValue-paid)}</strong></div><div class="detail-item"><span>Produção</span><strong>${esc(o.productionStage)}</strong></div><div class="detail-item"><span>Entrega</span><strong>${fmtDate(o.deliveryDate)}</strong></div><div class="detail-item"><span>Comissão</span><strong>${money(o.agreedValue*sellerCommission(resolveSellerUser(o))/100)}</strong></div></div><h3>Pagamento</h3><div class="grid two"><label class="field">Valor<input id="payVal" type="number" min="0" step="0.01"></label><label class="field">Data<input id="payDate" type="date" value="${today()}"></label></div><div class="actions" style="margin-top:10px"><button id="addPay" class="btn primary">Adicionar pagamento</button><button id="printOS" class="btn secondary">Imprimir OS de produção</button></div>`);$('addPay').onclick=()=>{const v=Number($('payVal').value),d=$('payDate').value;if(!v||!d)return alert('Informe valor e data.');o.payments=o.payments||[];o.payments.push({value:v,date:d,by:currentUsername(),at:new Date().toISOString()});queueSave();closeModal();renderOrders()};$('printOS').onclick=()=>{closeModal();printProductionOrder(o)}}
function printProductionOrder(o){const old=draft;draft={numero:o.quoteNumber,client:o.client,date:o.createdDate,address:o.address,contact:o.contact,seller:o.seller,travel:0,environments:clone(o.environments)};renderQuote();$('printQuoteTitle').textContent=`ORDEM DE PRODUÇÃO • PEDIDO ${String(o.numero).padStart(6,'0')}`;document.querySelectorAll('#envTable tr').forEach((tr,i)=>{const e=o.environments[i],c=e&&calcEnvironment(e);if(!c)return;tr.cells[0].innerHTML+=`<div class="print-only" style="font-size:8px">CORTE: acabamento ${c.finishCalc?.consumption.toFixed(2)||0}m; forro ${c.liningCalc?.consumption.toFixed(2)||0}m; ${c.finishCalc?.panels||0} / ${c.liningCalc?.panels||0} alturas; costura ${c.sewingMeters.toFixed(2)}m; deslizantes ${c.finishSliders+c.liningSliders}; ${esc(c.fixationCalc.detail)}.</div>`});$('view-quote').classList.add('print-target');window.print();setTimeout(()=>{draft=old;renderQuote();$('view-quote').classList.remove('print-target')},300)}

function renderProduction(){const box=$('productionList');if(!box)return;box.innerHTML='';for(const o of db.orders){const c=document.createElement('div');c.className='card';c.innerHTML=`<div class="card-title">Pedido ${String(o.numero).padStart(6,'0')} • ${esc(o.client)}</div><div class="stage-row">${STAGES.map(s=>`<button class="stage ${o.productionStage===s?'active':''}" data-stage-order="${o.numero}" data-stage="${s}">${s}</button>`).join('')}</div><p class="muted">Entrega: ${fmtDate(o.deliveryDate)} • ${o.environments?.length||0} ambiente(s). ${o.productionStage==='EXPEDIÇÃO'?'<strong>PEDIDO PRONTO PARA INSTALAÇÃO</strong>':''}</p>`;box.appendChild(c)}document.querySelectorAll('[data-stage-order]').forEach(b=>b.onclick=()=>{const o=db.orders.find(x=>Number(x.numero)===Number(b.dataset.stageOrder));if(!o)return;o.productionStage=b.dataset.stage;o.productionHistory=o.productionHistory||[];o.productionHistory.push({stage:b.dataset.stage,at:new Date().toISOString(),by:currentUsername()});queueSave();renderProduction();renderOrders();renderInstall()})}
function renderInstall(){const tb=$('installTable');if(!tb)return;tb.innerHTML='';for(const o of db.orders.slice().sort((a,b)=>String(a.deliveryDate).localeCompare(String(b.deliveryDate)))){const ready=o.productionStage==='EXPEDIÇÃO',done=!!o.installation?.completedDate;const tr=document.createElement('tr');tr.innerHTML=`<td>${fmtDate(o.deliveryDate)}</td><td>${String(o.numero).padStart(6,'0')}</td><td>${esc(o.client)}</td><td>${esc(o.productionStage)}</td><td><span class="badge ${done?'ok':ready?'blue':'warn'}">${done?'INSTALADO':ready?'PRONTO PARA INSTALAÇÃO':'EM PRODUÇÃO'}</span></td><td>${esc(o.installation?.responsible||'-')} ${ready&&!done?`<button class="btn ghost" data-install="${o.numero}">Atualizar</button>`:''}</td>`;tb.appendChild(tr)}document.querySelectorAll('[data-install]').forEach(b=>b.onclick=()=>openInstall(Number(b.dataset.install)))}
function openInstall(n){const o=db.orders.find(x=>Number(x.numero)===n);openModal(`<h2>Instalação • Pedido ${String(n).padStart(6,'0')}</h2><div class="grid two"><label class="field">Responsável<input id="instResp" value="${esc(o.installation?.responsible||'')}"></label><label class="field">Data concluída<input id="instDate" type="date" value="${o.installation?.completedDate||''}"></label></div><button id="instSave" class="btn primary">Salvar</button>`);$('instSave').onclick=()=>{o.installation={...(o.installation||{}),responsible:$('instResp').value.trim(),completedDate:$('instDate').value};queueSave();closeModal();renderInstall();renderOrders()}}

function productPrices(p){const base=Number(p.cost||0)*(1+Number(p.markup||0)/100);return {p4:base,p18:base*(1+db.priceConfig.terms.p18AddPct/100),cash:base*(1-db.priceConfig.terms.cashDiscountPct/100)}}
function officialMinimumStock(p){const cat=norm(p.category),name=norm(p.product_name);if(name.includes('MOTORIZAD')||(name.includes('VARÃO')&&name.includes('COMANDO')))return 0;if(name.includes('DESLIZANTE'))return 1000;if(cat.includes('TECIDO')||name.includes('TECIDO')||name.includes('LINHO')||name.includes('VOIL')||name.includes('BLACKOUT')||name.includes('FORRO')||name.includes('GABARDINE')||cat.includes('FITA')||name.includes('FITA'))return 80;if(cat.includes('TRILHO')||name.includes('TRILHO'))return 30;return 20}
function updateCombineButton(){const b=$('combineProductsBtn');if(!b)return;const n=selectedPriceProductIds.size;b.style.display=n>=2?'inline-flex':'none';b.textContent=n>=2?`Combinar Produtos (${n})`:'Combinar Produtos'}
async function reloadOfficialProducts(){const prices=await api('prices');priceProducts=Array.isArray(prices.products)?prices.products:[];for(const id of [...selectedPriceProductIds])if(!priceProducts.some(p=>Number(p.id)===Number(id)&&Number(p.active??1)===1))selectedPriceProductIds.delete(id);renderProducts()}
function renderProducts(){
 const tb=$('productsTable');if(!tb)return;const s=norm($('productSearch')?.value);tb.innerHTML='';
 const list=(priceProducts||[]).filter(p=>Number(p.active??1)===1).filter(p=>!s||norm(`${p.internal_code} ${p.supplier_code} ${p.category} ${p.supplier} ${p.product_name} ${p.color} ${p.ncm} ${p.cfop_internal} ${p.cfop_interstate}`).includes(s));
 for(const p of list){
   const unit=norm(p.unit||'UN'),qty=Number(p.stock_quantity||0),min=officialMinimumStock(p),critical=qty<min,tr=document.createElement('tr');
   if(critical)tr.style.cssText='background:#fff3b0;color:#b00020;font-weight:700';
   tr.innerHTML=`<td><input type="checkbox" data-price-select="${p.id}" ${selectedPriceProductIds.has(Number(p.id))?'checked':''}></td><td>${esc(p.internal_code||'-')}</td><td>${esc(p.supplier_code||'-')}</td><td>${esc(p.category||'-')}</td><td>${esc(p.supplier||'-')}</td><td>${esc(p.product_name||'-')}</td><td>${esc(p.color||'-')}</td><td>${qty.toFixed(unit==='M'?2:0)} ${esc(unit)}${critical?`<br><span class="badge warn">CRÍTICO • mín. ${min} ${esc(unit)}</span>`:''}</td><td>${money(p.cost)}</td><td>${Number(p.markup_percent||0)}%</td><td>${money(p.price_18x)}</td><td>${money(p.price_4x)}</td><td>${money(p.price_cash)}</td><td><div class="actions"><button class="btn ghost" data-price-edit="${p.id}">Editar Produto</button><button class="btn danger" data-price-delete="${p.id}">Excluir Produto</button></div></td>`;
   tb.appendChild(tr);
 }
 document.querySelectorAll('[data-price-select]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.priceSelect);if(el.checked)selectedPriceProductIds.add(id);else selectedPriceProductIds.delete(id);updateCombineButton()});
 document.querySelectorAll('[data-price-edit]').forEach(b=>b.onclick=()=>openOfficialProductEdit(Number(b.dataset.priceEdit)));
 document.querySelectorAll('[data-price-delete]').forEach(b=>b.onclick=()=>inactivateOfficialProduct(Number(b.dataset.priceDelete)));
 const all=(priceProducts||[]).filter(p=>Number(p.active??1)===1),criticalCount=all.filter(p=>Number(p.stock_quantity||0)<officialMinimumStock(p)).length;
 const costValue=all.reduce((a,p)=>a+Number(p.stock_quantity||0)*Number(p.cost||0),0),cashValue=all.reduce((a,p)=>a+Number(p.stock_quantity||0)*Number(p.price_cash||0),0);
 if($('inventorySummary'))$('inventorySummary').innerHTML=[['Produtos oficiais',all.length],['Estoque crítico',criticalCount],['Valor de custo em estoque',money(costValue)],['Valor total de venda à vista',money(cashValue)]].map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');updateCombineButton()
}
function openOfficialProductEdit(id){const p=(priceProducts||[]).find(x=>Number(x.id)===Number(id));if(!p)return;openModal(`<h2>Editar Produto • ${esc(p.internal_code)}</h2><p><strong>${esc(p.product_name)}</strong> • ${esc(p.color||'-')} • ${esc(p.supplier||'-')}</p><div class="grid two"><label class="field">Quantidade<input id="opQty" type="number" min="0" step="0.01" value="${Number(p.stock_quantity||0)}"></label><label class="field">Custo<input id="opCost" type="number" min="0" step="0.01" value="${Number(p.cost||0)}"></label><label class="field">Markup (%)<input id="opMarkup" type="number" min="0" step="0.01" value="${Number(p.markup_percent||0)}"></label><label class="field">Motivo da alteração<input id="opReason" placeholder="Obrigatório"></label></div><p class="muted">Os preços 4x, à vista e 18x serão recalculados automaticamente a partir do custo e markup.</p><button id="opSave" class="btn primary">Salvar alteração</button>`);$('opSave').onclick=async()=>{const reason=$('opReason').value.trim();if(!reason)return alert('Informe o motivo da alteração.');try{$('opSave').disabled=true;await api('prices',{method:'POST',body:JSON.stringify({action:'EDITAR',id:p.id,stock_quantity:Number($('opQty').value),cost:Number($('opCost').value),markup_percent:Number($('opMarkup').value),reason})});closeModal();await reloadOfficialProducts()}catch(e){alert(e.message)}finally{if($('opSave'))$('opSave').disabled=false}}}
async function inactivateOfficialProduct(id){const p=(priceProducts||[]).find(x=>Number(x.id)===Number(id));if(!p)return;const reason=prompt(`Motivo para excluir/inativar ${p.internal_code} • ${p.product_name}:`);if(reason===null)return;if(!reason.trim())return alert('Informe o motivo.');if(!confirm('O produto será inativado, preservando o histórico. Confirmar?'))return;try{await api('prices',{method:'POST',body:JSON.stringify({action:'INATIVAR',id:p.id,reason:reason.trim()})});selectedPriceProductIds.delete(Number(id));await reloadOfficialProducts()}catch(e){alert(e.message)}}
function openCombineProducts(){const items=(priceProducts||[]).filter(p=>selectedPriceProductIds.has(Number(p.id)));if(items.length<2)return alert('Selecione pelo menos dois produtos.');openModal(`<h2>Combinar Produtos</h2><p class="muted">${items.length} produtos selecionados.</p><div class="table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Produto</th><th>Saldo</th><th>Quantidade a usar</th></tr></thead><tbody>${items.map(p=>`<tr><td>${esc(p.internal_code)}</td><td>${esc(p.product_name)} / ${esc(p.color||'-')}</td><td>${Number(p.stock_quantity||0)} ${esc(p.unit||'')}</td><td><input data-combine-qty="${p.id}" type="number" min="0" step="0.01" value="0"></td></tr>`).join('')}</tbody></table></div><div class="notice">A seleção e a tela de combinação já estão prontas. A gravação da transformação será habilitada na próxima etapa do backend para garantir baixa transacional e histórico sem risco ao estoque.</div>`)}
function openProduct(p=null){
 const types=['TECIDO DE ACABAMENTO','TECIDO DE FORRO','TECIDO ESPECIAL','ACESSÓRIO','OUTRO'];
 openModal(`<h2>${p?'Editar':'Novo'} produto</h2><p class="muted">A combinação Tipo + Produto + Cor + Unidade é única. O código interno é automático se ficar vazio.</p><div class="grid two"><label class="field">Código interno<input id="pCode" value="${esc(p?.code||'')}" placeholder="Automático"></label><label class="field">Código do fornecedor<input id="pSupplierCode" value="${esc(p?.supplierCode||'')}"></label><label class="field">Tipo<select id="pType">${types.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Unidade<select id="pUnit"><option value="UN">UN</option><option value="M">M</option><option value="M2">M²</option><option value="KG">KG</option></select></label><label class="field">Categoria / observação<input id="pCat" value="${esc(p?.category||'')}"></label><label class="field">Nome<input id="pName" value="${esc(p?.name||'')}"></label><label class="field">Cor<input id="pColor" value="${esc(p?.color||'SEM COR')}"></label><label class="field">Largura da peça (cm)<input id="pRollWidth" type="number" value="${Number(p?.rollWidthCm||0)}"></label><label class="field">Quantidade<input id="pQty" type="number" step="0.01" value="${Number(p?.qty||0)}"></label><label class="field">Estoque mínimo<input id="pMin" type="number" step="0.01" value="${Number(p?.minimumStock||0)}"></label><label class="field">Custo de compra<input id="pCost" type="number" step="0.01" value="${Number(p?.cost||0)}"></label><label class="field">Markup (%)<input id="pMarkup" type="number" step="0.01" value="${Number(p?.markup??80)}"></label><label class="field" style="grid-column:1/-1">Motivo do ajuste de quantidade<input id="pReason" placeholder="Obrigatório quando alterar o saldo"></label></div><button id="pSave" class="btn primary">Salvar</button>`);
 if(p){$('pType').value=canonicalProductType(p.type);$('pUnit').value=p.unit||'UN'}
 $('pSave').onclick=()=>{const oldQty=Number(p?.qty||0),newQty=Number($('pQty').value||0),obj={...(p||{}),id:p?.id||uid(),code:$('pCode').value.trim()||p?.code||nextProductCode(),supplierCode:$('pSupplierCode').value.trim(),rollWidthCm:Number($('pRollWidth').value||0),type:$('pType').value,unit:$('pUnit').value,category:$('pCat').value.trim(),name:$('pName').value.trim(),color:$('pColor').value.trim()||'SEM COR',qty:newQty,minimumStock:Number($('pMin').value||0),cost:Number($('pCost').value||0),markup:Number($('pMarkup').value||0),stockManaged:p?.stockManaged!==false,movements:clone(p?.movements||[])};if(!obj.name)return alert('Informe o produto.');const dup=db.products.find(x=>x.id!==obj.id&&productIdentity(x.type,x.name,x.color,x.unit)===productIdentity(obj.type,obj.name,obj.color,obj.unit));if(dup)return alert(`Já existe este produto no estoque (${dup.code||dup.name}). Edite o cadastro existente para evitar duplicidade.`);if(obj.code&&db.products.some(x=>x.id!==obj.id&&norm(x.code)===norm(obj.code)))return alert('Já existe um produto com este código interno.');if(p&&Math.abs(newQty-oldQty)>1e-9){const reason=$('pReason').value.trim();if(!reason)return alert('Informe o motivo do ajuste manual da quantidade.');obj.movements.push({id:uid(),date:today(),at:new Date().toISOString(),type:'AJUSTE MANUAL',qty:newQty-oldQty,balance:newQty,unit:obj.unit,by:currentUsername(),reason})}const i=db.products.findIndex(x=>x.id===obj.id);if(i>=0)db.products[i]=obj;else db.products.unshift(obj);queueSave();closeModal();setupSelectors();renderProducts()}
}

function openPhysicalInventory(){const items=(db.products||[]).filter(p=>p.stockManaged).slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR'));if(!items.length)return alert('Não há produtos controlados em estoque.');openModal(`<h2>Inventário físico</h2><p class="muted">Informe a quantidade realmente contada. O sistema mostra a divergência e registra o ajuste no histórico somente após sua confirmação.</p><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Cor</th><th>Sistema</th><th>Contado</th></tr></thead><tbody>${items.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.color||'SEM COR')}</td><td>${Number(p.qty||0).toFixed(p.unit==='M'?2:0)} ${esc(p.unit||'')}</td><td><input data-count-id="${p.id}" type="number" step="0.01" value="${Number(p.qty||0)}" style="width:110px"></td></tr>`).join('')}</tbody></table></div><label class="field">Justificativa geral<input id="invReason" value="Inventário físico"></label><button id="invApply" class="btn primary" style="margin-top:12px">Aplicar divergências</button>`);$('invApply').onclick=()=>{const reason=$('invReason').value.trim();if(!reason)return alert('Informe a justificativa.');const changes=[];document.querySelectorAll('[data-count-id]').forEach(el=>{const p=db.products.find(x=>x.id===el.dataset.countId),counted=Number(el.value);if(!p||!Number.isFinite(counted)||counted<0)return;const old=Number(p.qty||0),diff=counted-old;if(Math.abs(diff)>1e-9)changes.push({p,counted,diff})});if(!changes.length)return alert('Nenhuma divergência encontrada.');if(!confirm(`Aplicar ${changes.length} ajuste(s) de inventário?`))return;for(const x of changes){x.p.qty=x.counted;x.p.movements=x.p.movements||[];x.p.movements.push({id:uid(),date:today(),at:new Date().toISOString(),type:'INVENTÁRIO FÍSICO',qty:x.diff,balance:x.counted,unit:x.p.unit,by:currentUsername(),reason})}queueSave();closeModal();setupSelectors();renderProducts()}}

function openProductHistory(p){if(!p)return;const rows=(p.movements||[]).slice().reverse().map(m=>`<tr><td>${fmtDate(m.date||String(m.at||'').slice(0,10))}</td><td>${esc(m.type||'-')}</td><td>${Number(m.qty||0)>0?'+':''}${Number(m.qty||0).toFixed(p.unit==='M'?2:0)} ${esc(m.unit||p.unit||'')}</td><td>${m.balance==null?'—':Number(m.balance).toFixed(p.unit==='M'?2:0)}</td><td>${esc(m.by||'-')}</td><td>${esc(m.reason||'-')}</td></tr>`).join('');openModal(`<h2>Histórico de estoque • ${esc(p.name)} / ${esc(p.color||'-')}</h2><table class="table"><thead><tr><th>Data</th><th>Movimento</th><th>Quantidade</th><th>Saldo</th><th>Responsável</th><th>Motivo / referência</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Nenhuma movimentação registrada.</td></tr>'}</tbody></table>`)}


function renderPricing(){const root=$('pricingForm');if(!root)return;const c=db.priceConfig;root.innerHTML=`<div class="grid two"><section class="card"><div class="card-title">Tecidos de acabamento</div>${Object.entries(c.finishes).map(([n,v])=>priceRow('finish',n,v.price)).join('')}</section><section class="card"><div class="card-title">Tecidos de forro</div>${Object.entries(c.linings).map(([n,v])=>priceRow('lining',n,v.price)).join('')}</section><section class="card"><div class="card-title">Mão de obra e aviamentos</div>${numField('sewing','Costura por metro',c.sewingPerMeter)}${numField('sliderFinish','Deslizante acabamento',c.sliders.finish)}${numField('sliderLining','Deslizante forro',c.sliders.lining)}${numField('swissClamp','Garra trilho suíço',c.swiss.clamp)}${numField('swissEnd','Acabamento trilho suíço',c.swiss.end)}${numField('waveMeter','Varão Wave / metro',c.wave.rodPerMeter)}${numField('waveSupport','Suporte Wave',c.wave.support)}${numField('waveEnd','Tampa Wave (não informada no documento)',c.wave.end)}</section><section class="card"><div class="card-title">Condições e automação</div>${numField('cashPct','Desconto à vista (%)',c.terms.cashDiscountPct)}${numField('p18Pct','Acréscimo 18x (%)',c.terms.p18AddPct)}${numField('cordPct','Comando por corda (%)',c.cordPct)}${numField('motorBase','Motor por folha',c.motor.basePerLeaf)}${numField('motorPct','Acréscimo ferragens motor (%)',c.motor.hardwarePct)}${numField('commDefault','Comissão padrão (%)',c.commissionDefault)}</section></div><section class="card" style="margin-top:14px"><div class="card-title">Instalação por altura</div><div class="grid four">${c.install.map((x,i)=>`<label class="field">Até ${x.maxH>=99?'acima de 6':x.maxH}m<input data-install-price="${i}" type="number" step="0.01" value="${x.price}"></label>`).join('')}</div></section>`}
function priceRow(kind,name,val){return `<label class="field" style="margin:8px 0">${esc(name)} (R$/m)<input data-price-kind="${kind}" data-price-name="${esc(name)}" type="number" step="0.01" value="${val}"></label>`}
function numField(id,label,val){return `<label class="field" style="margin:8px 0">${label}<input id="price-${id}" type="number" step="0.01" value="${val}"></label>`}
function savePricing(){document.querySelectorAll('[data-price-kind]').forEach(i=>{const k=i.dataset.priceKind,n=i.dataset.priceName,v=Number(i.value||0);if(k==='finish')db.priceConfig.finishes[n].price=v;else db.priceConfig.linings[n].price=v});db.priceConfig.sewingPerMeter=Number($('price-sewing').value);db.priceConfig.sliders.finish=Number($('price-sliderFinish').value);db.priceConfig.sliders.lining=Number($('price-sliderLining').value);db.priceConfig.swiss.clamp=Number($('price-swissClamp').value);db.priceConfig.swiss.end=Number($('price-swissEnd').value);db.priceConfig.wave.rodPerMeter=Number($('price-waveMeter').value);db.priceConfig.wave.support=Number($('price-waveSupport').value);db.priceConfig.wave.end=Number($('price-waveEnd').value);db.priceConfig.terms.cashDiscountPct=Number($('price-cashPct').value);db.priceConfig.terms.p18AddPct=Number($('price-p18Pct').value);db.priceConfig.cordPct=Number($('price-cordPct').value);db.priceConfig.motor.basePerLeaf=Number($('price-motorBase').value);db.priceConfig.motor.hardwarePct=Number($('price-motorPct').value);db.priceConfig.commissionDefault=Number($('price-commDefault').value);document.querySelectorAll('[data-install-price]').forEach(i=>db.priceConfig.install[Number(i.dataset.installPrice)].price=Number(i.value||0));queueSave();setupSelectors();renderAll();alert('Tabela de preços atualizada.')}

function renderKpis(){const cards=$('kpiCards'),seller=$('sellerKpis');if(!cards)return;const f=$('kpiFrom')?.value||'',t=$('kpiTo')?.value||'',sel=$('kpiSeller')?.value||'';const sellerSelect=$('kpiSeller');if(sellerSelect){const cur=sellerSelect.value;const names=[...new Set(db.orders.map(o=>resolveSellerUser(o)).filter(Boolean))].sort();sellerSelect.innerHTML='<option value="">LOJA TODA</option>'+names.map(n=>`<option value="${esc(n)}">${esc(sellerName(n))}</option>`).join('');sellerSelect.value=cur}const inRange=d=>{const x=(d||'').slice(0,10);return(!f||x>=f)&&(!t||x<=t)};const orders=db.orders.filter(o=>inRange(o.createdDate||o.date||'')&&(!sel||resolveSellerUser(o)===norm(sel)));const quotes=db.quotes.filter(q=>inRange(q.date||q.createdAt||'')&&(!sel||resolveSellerUser(q)===norm(sel)));const revenue=orders.reduce((a,o)=>a+Number(o.agreedValue||0),0),paid=orders.reduce((a,o)=>a+(o.payments||[]).reduce((ss,p)=>ss+Number(p.value||0),0),0),ticket=orders.length?revenue/orders.length:0,conversion=quotes.length?orders.length/quotes.length*100:0;cards.innerHTML=[['Orçamentos no período',quotes.length],['Pedidos efetivados',orders.length],['Saldo a receber',money(Math.max(0,revenue-paid))],['Conversão',conversion.toFixed(1)+'%'],['Ticket médio',money(ticket)],['Faturamento',money(revenue)],['Retrabalhos',db.reworks.filter(r=>inRange(r.date||'')).length],['Em produção',orders.filter(o=>o.productionStage!=='EXPEDIÇÃO').length]].map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');const by={};for(const o of orders){const k=resolveSellerUser(o)||'-';by[k]??={count:0,total:0};by[k].count++;by[k].total+=Number(o.agreedValue||0)}seller.innerHTML=Object.entries(by).map(([k,v])=>`<div class="detail-item" style="margin:6px 0"><span>${esc(sellerName(k))}</span><strong>${v.count} pedido(s) • ${money(v.total)} • Comissão estimada ${money(v.total*sellerCommission(k)/100)}</strong></div>`).join('')||'<p class="muted">Nenhum pedido no filtro selecionado.</p>'}

function printKpis(){renderKpis();const f=$('kpiFrom')?.value||'',t=$('kpiTo')?.value||'',sel=$('kpiSeller')?.value||'LOJA TODA';const cards=[...document.querySelectorAll('#kpiCards .kpi')].map(x=>`<div style="border:1px solid #c7d3d2;padding:8px"><div>${x.querySelector('span')?.textContent||''}</div><strong>${x.querySelector('strong')?.textContent||''}</strong></div>`).join('');printWindow(`<h2>RELATÓRIO DE KPIs</h2><p><strong>Período:</strong> ${f?fmtDate(f):'início'} até ${t?fmtDate(t):'hoje'} &nbsp; <strong>Vendedor:</strong> ${esc(sel)}</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px">${cards}</div><h3>Vendas por vendedor</h3>${$('sellerKpis')?.innerHTML||''}`)}
function payableStatus(p){const paid=Number(p.paidValue||0);const val=Number(p.value||0);if(val>0&&paid>=val-0.005)return'PAGO';if(p.paidDate&&paid>0)return paid>=val-0.005?'PAGO':'PENDENTE';if(p.dueDate&&p.dueDate<today())return'EM ATRASO';return'PENDENTE'}
function renderPayables(){const tb=$('payablesTable');if(!tb)return;const f=$('payFrom')?.value||'',t=$('payTo')?.value||'',st=$('payStatus')?.value||'';const all=db.payables||[];const list=all.filter(p=>(!f||p.dueDate>=f)&&(!t||p.dueDate<=t)&&(!st||payableStatus(p)===st));tb.innerHTML='';for(const p of list){const status=payableStatus(p),tr=document.createElement('tr');tr.innerHTML=`<td>${esc(p.documentNumber||p.title)}</td><td>${esc(p.definition||'-')}</td><td>${esc(p.quoteNumber||p.purchaseOrder||'-')}</td><td>${fmtDate(p.dueDate)}</td><td>${money(p.value)}</td><td>${money(p.paidValue)}</td><td>${fmtDate(p.paidDate)}</td><td><span class="badge ${status==='PAGO'?'ok':status==='EM ATRASO'?'danger':'warn'}">${status}</span></td><td><button class="btn ghost" data-payable-edit="${p.id}">Editar</button> <button class="btn danger" data-payable-del="${p.id}">Excluir</button></td>`;tb.appendChild(tr)}const sum=x=>x.reduce((a,p)=>a+Number(p.value||0),0),paid=x=>x.reduce((a,p)=>a+Number(p.paidValue||0),0),pending=x=>x.reduce((a,p)=>a+Math.max(0,Number(p.value||0)-Number(p.paidValue||0)),0),late=x=>x.filter(p=>payableStatus(p)==='EM ATRASO').reduce((a,p)=>a+Math.max(0,Number(p.value||0)-Number(p.paidValue||0)),0);if($('payableSummary'))$('payableSummary').innerHTML=[['Total geral',money(sum(all))],['Total filtrado',money(sum(list))],['Pago no filtro',money(paid(list))],['A pagar no filtro',money(pending(list))],['Em atraso',money(late(list))]].map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');document.querySelectorAll('[data-payable-edit]').forEach(b=>b.onclick=()=>openPayable(db.payables.find(x=>x.id===b.dataset.payableEdit)));document.querySelectorAll('[data-payable-del]').forEach(b=>b.onclick=()=>{if(confirm('Excluir este título definitivamente?')){db.payables=db.payables.filter(x=>x.id!==b.dataset.payableDel);queueSave();renderPayables()}})}
function openPayable(p=null){openModal(`<h2>${p?'Editar':'Novo'} título</h2><div class="grid two"><label class="field">Título / documento<input id="apTitle" value="${esc(p?.documentNumber||p?.title||'')}"></label><label class="field">Definição<input id="apDef" value="${esc(p?.definition||'')}"></label><label class="field">Referência<input id="apQuote" value="${esc(p?.quoteNumber||p?.purchaseOrder||'')}"></label><label class="field">Vencimento<input id="apDue" type="date" value="${p?.dueDate||''}"></label><label class="field">Valor<input id="apValue" type="number" step="0.01" value="${Number(p?.value||0)}"></label><label class="field">Valor pago<input id="apPaid" type="number" step="0.01" value="${Number(p?.paidValue||0)}"></label><label class="field">Data pagamento<input id="apPaidDate" type="date" value="${p?.paidDate||''}"></label><label class="field">Observações<textarea id="apNotes">${esc(p?.notes||'')}</textarea></label></div><button id="apSave" class="btn primary">Salvar</button>`);$('apSave').onclick=()=>{const doc=$('apTitle').value.trim();const obj={...(p||{}),id:p?.id||uid(),title:doc,documentNumber:doc,definition:$('apDef').value.trim(),quoteNumber:$('apQuote').value.trim(),dueDate:$('apDue').value,value:Number($('apValue').value||0),paidValue:Number($('apPaid').value||0),paidDate:$('apPaidDate').value,notes:$('apNotes').value.trim()};if(!obj.title)return alert('Informe o título/documento.');const i=db.payables.findIndex(x=>x.id===obj.id);if(i>=0)db.payables[i]=obj;else db.payables.unshift(obj);queueSave();closeModal();renderPayables()}}

function renderSuppliers(){const root=$('supplierList');if(!root)return;root.innerHTML='';for(const x of db.suppliers||[]){const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(x.name)}</td><td>${esc(x.cnpj||'-')}</td><td>${esc(x.contact||'-')}</td><td>${esc(x.productType||'-')}</td><td>${esc(x.condition||'-')}</td><td>${Number(x.avgDays||0)} dias</td><td><div class="actions"><button class="btn ghost" data-sup-edit="${x.id}">Editar fornecedor</button><button class="btn secondary" data-sup-order="${x.id}">Nova ordem de compra</button><button class="btn danger" data-sup-del="${x.id}">Excluir</button></div></td>`;root.appendChild(tr)}document.querySelectorAll('[data-sup-edit]').forEach(b=>b.onclick=()=>openSupplier(db.suppliers.find(x=>x.id===b.dataset.supEdit)));document.querySelectorAll('[data-sup-order]').forEach(b=>b.onclick=()=>openPurchase(null,b.dataset.supOrder));document.querySelectorAll('[data-sup-del]').forEach(b=>b.onclick=()=>{const has=(db.purchaseOrders||[]).some(o=>o.supplierId===b.dataset.supDel);if(has&&!confirm('Este fornecedor possui ordens de compra. Deseja excluir o cadastro mesmo assim?'))return;if(!has&&!confirm('Excluir fornecedor?'))return;db.suppliers=db.suppliers.filter(x=>x.id!==b.dataset.supDel);queueSave();renderSuppliers()})}
function openSupplier(s=null){openModal(`<h2>${s?'Editar':'Novo'} fornecedor</h2><div class="grid two"><label class="field">Razão social<input id="supName" value="${esc(s?.name||'')}"></label><label class="field">CNPJ<input id="supCnpj" value="${esc(s?.cnpj||'')}"></label><label class="field">Responsável / contato<input id="supContact" value="${esc(s?.contact||'')}"></label><label class="field">Telefone / e-mail<input id="supContactInfo" value="${esc(s?.contactInfo||'')}"></label><label class="field">Tipo de material<input id="supType" value="${esc(s?.productType||'')}"></label><label class="field">Condição de venda<input id="supCond" value="${esc(s?.condition||'')}"></label><label class="field">Prazo médio entrega (dias)<input id="supDays" type="number" value="${Number(s?.avgDays||0)}"></label><label class="field">Observações<textarea id="supNotes">${esc(s?.notes||'')}</textarea></label></div><button id="supSave" class="btn primary">Salvar</button>`);$('supSave').onclick=()=>{const obj={id:s?.id||uid(),name:$('supName').value.trim(),cnpj:$('supCnpj').value.trim(),contact:$('supContact').value.trim(),contactInfo:$('supContactInfo').value.trim(),productType:$('supType').value.trim(),condition:$('supCond').value.trim(),avgDays:Number($('supDays').value||0),notes:$('supNotes').value.trim()};if(!obj.name)return alert('Informe a razão social.');const i=db.suppliers.findIndex(x=>x.id===obj.id);if(i>=0)db.suppliers[i]=obj;else db.suppliers.unshift(obj);queueSave();closeModal();renderSuppliers()}}

function renderReworks(){const tb=$('reworksTable');if(!tb)return;tb.innerHTML='';for(const r of db.reworks){const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(r.number)}</td><td>${esc(r.orderNumber)}</td><td>${fmtDate(r.date)}</td><td>${esc(r.summary)}</td><td><span class="badge warn">${esc(r.status)}</span></td>`;tb.appendChild(tr)}}
function openRework(){openModal(`<h2>Novo retrabalho</h2><div class="grid two"><label class="field">Pedido<input id="rwOrder"></label><label class="field">Data<input id="rwDate" type="date" value="${today()}"></label><label class="field" style="grid-column:1/-1">Resumo<textarea id="rwSummary"></textarea></label></div><button id="rwSave" class="btn primary">Salvar</button>`);$('rwSave').onclick=()=>{const order=$('rwOrder').value.trim(),summary=$('rwSummary').value.trim();if(!order||!summary)return alert('Informe pedido e resumo.');db.reworks.unshift({id:uid(),number:`RT-${String(db.reworks.length+1).padStart(4,'0')}`,orderNumber:order,date:$('rwDate').value,summary,status:'ABERTO'});queueSave();closeModal();renderReworks()}}

function renderUsers(){const tb=$('usersTable');if(!tb)return;const disabled=new Set((db.disabledUsers||[]).map(norm));tb.innerHTML='';for(const u0 of [...DEFAULT_USERS,...db.users].filter((u,i,a)=>a.findIndex(x=>norm(x.username)===norm(u.username))===i)){const u=userPermissionRecord(u0.username),dis=disabled.has(norm(u.username));const perms=(u.permissions||[]).includes('*')?'TODAS':(u.permissions||[]).map(k=>NAV.find(n=>n[0]===k)?.[1]||k).join(', ')||'Padrão do perfil';const tr=document.createElement('tr');tr.innerHTML=`<td>${esc(u.username)}</td><td>${esc(u.name||'-')}</td><td>${esc(u.role)}</td><td>${Number(u.commission||0)}%</td><td style="max-width:260px">${esc(perms)}</td><td>${esc(u.createdBy||(u.builtIn?'SISTEMA':'-'))}</td><td>${u.createdAt?fmtDate(u.createdAt.slice(0,10)):'-'}</td><td><span class="badge ${dis?'danger':'ok'}">${dis?'DESATIVADO':'ATIVO'}</span> ${isGestor()?`<button class="btn ghost" data-user-profile="${esc(u.username)}">Editar</button> <button class="btn ghost" data-user-pass="${esc(u.username)}">Senha</button> <button class="btn ghost" data-user-edit="${esc(u.username)}">Permissões</button> <button class="btn danger" data-user-del="${esc(u.username)}">${u.builtIn?(dis?'Reativar':'Desativar'):'Excluir'}</button>`:''}</td>`;tb.appendChild(tr)}document.querySelectorAll('[data-user-profile]').forEach(b=>b.onclick=()=>openUserProfile(b.dataset.userProfile));document.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>openUserPermissions(b.dataset.userEdit));document.querySelectorAll('[data-user-pass]').forEach(b=>b.onclick=()=>openResetPassword(b.dataset.userPass));document.querySelectorAll('[data-user-del]').forEach(b=>b.onclick=()=>deleteUser(b.dataset.userDel))}

function openUserProfile(username){if(!isGestor())return;const key=norm(username),custom=(db.users||[]).find(x=>norm(x.username)===key),u=userPermissionRecord(username);openModal(`<h2>Editar usuário • ${esc(username)}</h2><div class="grid two"><label class="field">Nome completo<input id="ueName" value="${esc(u.name||'')}"></label><label class="field">Perfil<select id="ueRole"><option value="sales">VENDAS</option><option value="production">PRODUÇÃO</option><option value="gestor">GESTOR</option></select></label><label class="field">Comissão (%)<input id="ueComm" type="number" step="0.01" value="${Number(u.commission||0)}"></label><div class="field"><span>Login</span><strong>${esc(username)}</strong></div></div><p class="muted">O login é a identidade permanente do vendedor e não é alterado para preservar o histórico.</p><button id="ueSave" class="btn primary">Salvar</button>`);$('ueRole').value=u.role||'sales';$('ueSave').onclick=async()=>{if(custom){custom.name=$('ueName').value.trim()||custom.name;custom.role=$('ueRole').value;custom.commission=Number($('ueComm').value||0)}else{db.settings=db.settings||{};db.settings.builtInUserProfiles=db.settings.builtInUserProfiles||{};db.settings.builtInUserProfiles[key]={name:$('ueName').value.trim()||u.name,role:$('ueRole').value,commission:Number($('ueComm').value||0)}}await saveCloud();closeModal();renderUsers();refreshSellerControl(draft.sellerUser)}}

function openResetPassword(username){if(!isGestor())return;openModal(`<h2>Redefinir senha • ${esc(username)}</h2><p class="muted">O Gestor define uma nova senha sem visualizar a senha atual.</p><label class="field">Nova senha<input id="resetPass" type="password" minlength="6"></label><label class="field">Confirmar nova senha<input id="resetPass2" type="password" minlength="6"></label><button id="resetPassSave" class="btn primary" style="margin-top:12px">Alterar senha</button>`);$('resetPassSave').onclick=async()=>{const a=$('resetPass').value,b=$('resetPass2').value;if(a.length<6)return alert('A senha precisa ter pelo menos 6 caracteres.');if(a!==b)return alert('As senhas não conferem.');const custom=(db.users||[]).find(x=>norm(x.username)===norm(username));const hash=await sha256(a);if(custom)custom.hash=hash;else{db.settings=db.settings||{};db.settings.userPasswordOverrides=db.settings.userPasswordOverrides||{};db.settings.userPasswordOverrides[norm(username)]=hash}await saveCloud();closeModal();alert('Senha alterada. Ela valerá no próximo login.')}}
function deleteUser(username){if(!isGestor())return alert('Apenas o GESTOR pode gerenciar usuários.');const u=[...DEFAULT_USERS,...db.users].find(x=>norm(x.username)===norm(username));if(!u)return;if(norm(username)===currentUsername())return alert('Você não pode excluir/desativar o usuário atualmente conectado.');db.disabledUsers=db.disabledUsers||[];if(u.builtIn){const i=db.disabledUsers.findIndex(x=>norm(x)===norm(username));if(i>=0){if(!confirm('Reativar este usuário?'))return;db.disabledUsers.splice(i,1)}else{if(!confirm('Desativar este usuário?'))return;db.disabledUsers.push(norm(username))}}else{if(!confirm('Excluir definitivamente este usuário?'))return;db.users=db.users.filter(x=>norm(x.username)!==norm(username));db.disabledUsers=db.disabledUsers.filter(x=>norm(x)!==norm(username));if(db.settings?.userPermissions)delete db.settings.userPermissions[norm(username)]}queueSave();renderUsers()}
function permissionChecklist(selected=[]){const set=new Set(selected);return `<div class="permission-grid">${NAV.map(([id,label])=>`<label class="perm"><input type="checkbox" data-perm="${id}" ${set.has('*')||set.has(id)?'checked':''}> ${esc(label)}</label>`).join('')}</div>`}
function collectPermissions(){return [...document.querySelectorAll('[data-perm]:checked')].map(x=>x.dataset.perm)}
function openUserPermissions(username){if(!isGestor())return;const u=userPermissionRecord(username);openModal(`<h2>Permissões • ${esc(username)}</h2><p>Marque as áreas que este usuário poderá ver e editar.</p>${permissionChecklist(u.permissions||(u.role==='gestor'?['*']:u.role==='production'?['orders','production','install']:['quote','quotes','clients','orders','install']))}<button id="permSave" class="btn primary" style="margin-top:12px">Salvar permissões</button>`);$('permSave').onclick=()=>{db.settings=db.settings||{};db.settings.userPermissions=db.settings.userPermissions||{};db.settings.userPermissions[norm(username)]=collectPermissions();queueSave();closeModal();renderUsers()}}
function openUser(){openModal(`<h2>Novo usuário</h2><div class="grid two"><label class="field">Usuário<input id="uUser"></label><label class="field">Nome completo<input id="uName"></label><label class="field">Senha<input id="uPass" type="password"></label><label class="field">Perfil<select id="uRole"><option value="sales">VENDAS</option><option value="production">PRODUÇÃO</option><option value="gestor">GESTOR</option></select></label><label class="field">Comissão (%)<input id="uComm" type="number" value="${db.priceConfig.commissionDefault||5}"></label></div><h3>Áreas que poderá acessar</h3>${permissionChecklist(['quote','quotes','clients','orders','install'])}<button id="uSave" class="btn primary" style="margin-top:12px">Criar usuário</button>`);$('uRole').onchange=()=>{const role=$('uRole').value,def=role==='gestor'?permissionKeys():role==='production'?['orders','production','install']:['quote','quotes','clients','orders','install'];document.querySelectorAll('[data-perm]').forEach(x=>x.checked=def.includes(x.dataset.perm))};$('uSave').onclick=async()=>{const username=norm($('uUser').value),name=$('uName').value.trim(),pass=$('uPass').value,role=$('uRole').value;if(username.length<3||pass.length<6)return alert('Usuário deve ter 3+ caracteres e senha 6+ caracteres.');if(allUsers().some(x=>norm(x.username)===username))return alert('Usuário já existe.');db.users.push({username,name,role,commission:Number($('uComm').value||0),hash:await sha256(pass),builtIn:false,createdBy:currentUsername(),createdAt:new Date().toISOString(),permissions:collectPermissions()});await saveCloud();closeModal();renderUsers();alert('Usuário criado e liberado para login.')}}

function openModal(html){$('modalBody').innerHTML=html;$('modal').classList.add('open')}function closeModal(){$('modal').classList.remove('open');$('modalBody').innerHTML=''}

async function doLogin(){const user=norm($('loginUser').value),pass=$('loginPass').value;if(!user||!pass)return $('loginError').textContent='Informe usuário e senha.';try{$('loginBtn').disabled=true;$('loginError').textContent='';const j=await api('auth',{method:'POST',body:JSON.stringify({username:user,passwordHash:await sha256(pass)})});token=j.token;currentUser={username:j.username,role:j.role,name:j.name||j.username};sessionStorage.setItem('novaV9Token',token);sessionStorage.setItem('novaV9User',JSON.stringify(currentUser));document.body.classList.remove('auth-locked');$('loginScreen').classList.add('hidden');$('sessionUser').textContent=`${j.name||j.username} • ${String(j.role).toUpperCase()}`;draft.sellerUser=norm(j.username);draft.seller=sellerName(j.username);await loadCloud();refreshSellerControl(draft.sellerUser);setupSelectors();renderQuote();goHome()}catch(e){$('loginError').textContent=e.message}finally{$('loginBtn').disabled=false}}
function logout(){sessionStorage.removeItem('novaV9Token');sessionStorage.removeItem('novaV9User');location.reload()}
async function restore(){if(!token||!currentUser)return false;try{await api('data');document.body.classList.remove('auth-locked');$('loginScreen').classList.add('hidden');$('sessionUser').textContent=`${currentUser.name||currentUser.username} • ${String(currentUser.role).toUpperCase()}`;await loadCloud();setupSelectors();goHome();return true}catch{token='';currentUser=null;sessionStorage.clear();return false}}


function openLooseProduct(){
  const available=(db.products||[]).filter(p=>p.stockManaged&&Number(p.qty||0)>0).sort((a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR'));
  if(!available.length)return alert('Não há produtos disponíveis no estoque.');
  openModal(`<h2>Adicionar Produto Avulso</h2><p class="muted">Venda de tecido, trilho, varão, suporte, fita ou acessório sem criar ambiente. O preço padrão vem do estoque e pode ser alterado com justificativa.</p><div class="grid two"><label class="field">Produto<select id="lpProduct">${available.map(p=>`<option value="${p.id}">${esc(p.name)} • ${esc(p.color||'SEM COR')} • saldo ${Number(p.qty||0).toFixed(p.unit==='M'?2:0)} ${esc(p.unit||'')}</option>`).join('')}</select></label><label class="field">Quantidade<input id="lpQty" type="number" step="0.01" min="0.01" value="1"></label><label class="field" style="grid-column:1/-1">Descrição no orçamento<input id="lpDesc" placeholder="Opcional; por padrão usa o nome do produto"></label><label class="field">Preço à vista unitário<input id="lpCash" type="number" step="0.01"></label><label class="field">Justificativa da alteração<input id="lpReason" placeholder="Obrigatória somente se alterar o preço"></label></div><div id="lpPreview" class="notice"></div><button id="lpSave" class="btn primary">Adicionar produto</button>`);
  const productEl=$('lpProduct'), saveEl=$('lpSave'), qtyEl=$('lpQty'), cashEl=$('lpCash'), reasonEl=$('lpReason'), descEl=$('lpDesc'), previewEl=$('lpPreview');
  if(!productEl||!saveEl||!qtyEl||!cashEl||!reasonEl||!descEl||!previewEl){console.warn('Modal de produto avulso incompleto; ação cancelada.');return}
  productEl.onchange=()=>{const p=db.products.find(x=>x.id===productEl.value);if(!p)return;const pr=productPrices(p);cashEl.value=pr.cash.toFixed(2);previewEl.textContent=`Preço padrão à vista: ${money(pr.cash)} • 4x: ${money(pr.p4)} • 18x: ${money(pr.p18)}`;descEl.placeholder=p.name};
  productEl.dispatchEvent(new Event('change'));
  saveEl.onclick=()=>{const p=db.products.find(x=>x.id===productEl.value),qty=Number(qtyEl.value||0);if(!p||qty<=0)return alert('Informe produto e quantidade.');if(qty>Number(p.qty||0)+1e-9)return alert(`Estoque insuficiente. Disponível: ${p.qty} ${p.unit}.`);const std=productPrices(p),cash=Number(cashEl.value||0),reason=reasonEl.value.trim(),changed=Math.abs(cash-std.cash)>0.01;if(changed&&!reason)return alert('Informe a justificativa da alteração do preço.');const factor=std.cash>0?cash/std.cash:1;draft.looseProducts=draft.looseProducts||[];draft.looseProducts.push({id:uid(),productId:p.id,stockManaged:true,type:p.type,name:p.name,color:p.color,unit:p.unit,qty,description:descEl.value.trim()||p.name,standardCash:std.cash,cash,p4:std.p4*factor,p18:std.p18*factor,priceOverride:changed,priceReason:reason});closeModal();renderQuote()}
}


function openSpecialProduct(){openModal(`<h2>Produto Fora de Estoque</h2><p class="muted">Use para um item especial comprado especificamente para este pedido. Ele não cria saldo positivo no estoque.</p><div class="grid two"><label class="field">Tipo<select id="spType"><option>TECIDO ESPECIAL</option><option>ACESSÓRIO</option><option>OUTRO</option><option>TECIDO DE ACABAMENTO</option><option>TECIDO DE FORRO</option></select></label><label class="field">Produto<input id="spName"></label><label class="field">Cor / modelo<input id="spColor"></label><label class="field">Unidade<select id="spUnit"><option>UN</option><option>M</option><option value="M2">M²</option><option>KG</option></select></label><label class="field">Quantidade<input id="spQty" type="number" step="0.01" value="1"></label><label class="field">Descrição no orçamento<input id="spDesc"></label><label class="field">18x unitário<input id="sp18" type="number" step="0.01"></label><label class="field">4x unitário<input id="sp4" type="number" step="0.01"></label><label class="field">À vista unitário<input id="spCash" type="number" step="0.01"></label><label class="field">Observação / motivo<input id="spReason" placeholder="Ex.: item sob encomenda"></label></div><button id="spSave" class="btn primary">Adicionar</button>`);$('spSave').onclick=()=>{const name=$('spName').value.trim(),qty=Number($('spQty').value||0);if(!name||qty<=0)return alert('Informe produto e quantidade.');draft.looseProducts=draft.looseProducts||[];draft.looseProducts.push({id:uid(),stockManaged:false,type:canonicalProductType($('spType').value),name,color:$('spColor').value.trim()||'SEM COR',unit:$('spUnit').value,qty,description:$('spDesc').value.trim()||name,p18:Number($('sp18').value||0),p4:Number($('sp4').value||0),cash:Number($('spCash').value||0),specialReason:$('spReason').value.trim(),outsideStock:true});closeModal();renderQuote()}}

function openBlind(){openModal(`<h2>Incluir persiana</h2><p class="muted">Informe manualmente os dados e valores trazidos do sistema da Amorim. O ERP não calcula o preço da persiana.</p><div class="grid two"><label class="field">Ambiente<input id="bEnv"></label><label class="field">Modelo<input id="bModel"></label><label class="field">Cor<input id="bColor"></label><label class="field">Bandô<input id="bBando"></label><label class="field">Largura (cm)<input id="bW" type="number"></label><label class="field">Altura (cm)<input id="bH" type="number"></label><label class="field">Quantidade (un.)<input id="bQty" type="number" min="1" value="1"></label><label class="field">Lado do comando<select id="bCmd"><option>DIREITO</option><option>ESQUERDO</option><option>SEM COMANDO</option></select></label><label class="field">18x por unidade (R$)<input id="b18" type="number" step="0.01"></label><label class="field">4x por unidade (R$)<input id="b4" type="number" step="0.01"></label><label class="field">À vista por unidade (R$)<input id="bCash" type="number" step="0.01"></label></div><button id="bSave" class="btn primary">Adicionar persiana</button>`);$('bSave').onclick=()=>{const w=Number($('bW').value),h=Number($('bH').value),qty=Math.max(1,Number($('bQty').value||1));const b={id:uid(),environment:$('bEnv').value.trim()||'PERSIANA',model:$('bModel').value.trim(),color:$('bColor').value.trim(),bando:$('bBando').value.trim(),width:w,height:h,qty,area:(w/100)*(h/100),commandSide:$('bCmd').value,p18:Number($('b18').value||0),p4:Number($('b4').value||0),cash:Number($('bCash').value||0)};if(!b.model||!w||!h)return alert('Informe modelo, largura e altura.');draft.blinds=draft.blinds||[];draft.blinds.push(b);closeModal();renderQuote()}}
function renderPurchases(){const tb=$('purchaseTable');if(!tb)return;db.purchaseOrders=db.purchaseOrders||[];tb.innerHTML='';for(const o of db.purchaseOrders){const st=o.status||'ABERTA',received=['RECEBIDA','FINALIZADA'].includes(st),tr=document.createElement('tr');tr.innerHTML=`<td>${esc(o.number)}</td><td>${esc(o.supplierName)}</td><td>${esc(o.responsible||'-')}</td><td>${esc(o.requester||'-')}</td><td>${fmtDate(o.date)}</td><td><span class="badge ${st==='FINALIZADA'?'ok':received?'blue':'warn'}">${esc(st)}</span></td><td><button class="btn ${received?'ghost':'primary'}" data-po-receive="${o.id}">${received?'Recebida':'Confirmar recebimento'}</button></td><td><button class="btn secondary" data-po-values="${o.id}" ${!received?'disabled title="Confirme o recebimento primeiro"':''}>Inserir valores</button></td><td><button class="btn ghost" data-po-edit="${o.id}">Abrir</button> <button class="btn ghost" data-po-print="${o.id}">PDF</button></td>`;tb.appendChild(tr)}document.querySelectorAll('[data-po-edit]').forEach(b=>b.onclick=()=>openPurchase(db.purchaseOrders.find(x=>x.id===b.dataset.poEdit)));document.querySelectorAll('[data-po-print]').forEach(b=>b.onclick=()=>printPurchase(db.purchaseOrders.find(x=>x.id===b.dataset.poPrint)));document.querySelectorAll('[data-po-receive]').forEach(b=>b.onclick=()=>openPurchaseReceipt(db.purchaseOrders.find(x=>x.id===b.dataset.poReceive)));document.querySelectorAll('[data-po-values]').forEach(b=>b.onclick=()=>openPurchaseValues(db.purchaseOrders.find(x=>x.id===b.dataset.poValues)))}
function openPurchase(o=null,presetSupplierId=''){db.purchaseOrders=db.purchaseOrders||[];const sups=db.suppliers.map(s=>`<option value="${s.id}" ${(o?.supplierId||presetSupplierId)===s.id?'selected':''}>${esc(s.name)}</option>`).join('');openModal(`<h2>${o?'Ordem '+esc(o.number):'Nova Ordem de Compra'}</h2><div class="grid two"><label class="field">Fornecedor<select id="poSup"><option value="">Selecione</option>${sups}</select></label><label class="field">Data da compra<input id="poDate" type="date" value="${o?.date||today()}"></label><label class="field">Responsável<input id="poResp" value="${esc(o?.responsible||sellerName(currentUser?.username))}"></label><label class="field">Solicitante<input id="poRequester" value="${esc(o?.requester||sellerName(currentUser?.username))}"></label><label class="field" style="grid-column:1/-1">Observações<textarea id="poNotes">${esc(o?.notes||'')}</textarea></label></div><h3>Produtos solicitados</h3><p class="muted">Escolha primeiro o TIPO. Se a combinação já existir, o recebimento soma ao mesmo cadastro; não cria duplicidade.</p><div id="poItems"></div><button id="poAdd" class="btn secondary">+ Produto</button> <button id="poConfirm" class="btn primary">${o?'Salvar alterações':'Criar Ordem de Compra'}</button>`);let items=clone(o?.items||[]);const types=['TECIDO DE ACABAMENTO','TECIDO DE FORRO','TECIDO ESPECIAL','ACESSÓRIO','OUTRO'];const draw=()=>{$('poItems').innerHTML=items.map((x,i)=>`<div class="grid four purchase-item"><label class="field">Tipo<select data-pt="${i}">${types.map(t=>`<option ${canonicalProductType(x.materialType)===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Produto<input data-pn="${i}" value="${esc(x.name||'')}" list="stockNames"></label><label class="field">Cor<input data-pcolor="${i}" value="${esc(x.color||'SEM COR')}"></label><label class="field">Unidade<select data-punit="${i}"><option ${x.unit==='M'?'selected':''}>M</option><option ${x.unit==='UN'?'selected':''}>UN</option><option ${x.unit==='M2'?'selected':''} value="M2">M²</option><option ${x.unit==='KG'?'selected':''}>KG</option></select></label><label class="field">Cód. fornecedor<input data-pc="${i}" value="${esc(x.supplierCode||'')}"></label><label class="field">Quantidade<input data-pq="${i}" type="number" step="0.01" value="${Number(x.qty||1)}"></label><button class="btn danger" data-prm="${i}" type="button">Remover</button></div>`).join('')+`<datalist id="stockNames">${uniqueSorted((db.products||[]).map(p=>p.name)).map(n=>`<option value="${esc(n)}">`).join('')}</datalist>`;document.querySelectorAll('[data-pt]').forEach(el=>el.oninput=()=>items[el.dataset.pt].materialType=el.value);document.querySelectorAll('[data-pn]').forEach(el=>el.oninput=()=>items[el.dataset.pn].name=el.value);document.querySelectorAll('[data-pcolor]').forEach(el=>el.oninput=()=>items[el.dataset.pcolor].color=el.value);document.querySelectorAll('[data-punit]').forEach(el=>el.oninput=()=>items[el.dataset.punit].unit=el.value);document.querySelectorAll('[data-pc]').forEach(el=>el.oninput=()=>items[el.dataset.pc].supplierCode=el.value);document.querySelectorAll('[data-pq]').forEach(el=>el.oninput=()=>items[el.dataset.pq].qty=Number(el.value));document.querySelectorAll('[data-prm]').forEach(el=>el.onclick=()=>{items.splice(Number(el.dataset.prm),1);draw()})};draw();$('poAdd').onclick=()=>{items.push({materialType:'OUTRO',name:'',color:'SEM COR',unit:'UN',supplierCode:'',qty:1});draw()};$('poConfirm').onclick=()=>{const sid=$('poSup').value,sup=db.suppliers.find(x=>x.id===sid);if(!sid||!items.length)return alert('Selecione o fornecedor e adicione ao menos um produto.');if(items.some(x=>!String(x.name||'').trim()))return alert('Preencha o produto de todos os itens.');const obj={...(o||{}),id:o?.id||uid(),number:o?.number||`OC-${String((db.settings.nextPurchaseNumber||1)).padStart(6,'0')}`,date:$('poDate').value,responsible:$('poResp').value.trim(),requester:$('poRequester').value.trim(),supplierId:sid,supplierName:sup.name,supplierCnpj:sup.cnpj||'',supplierContact:sup.contact||'',notes:$('poNotes').value.trim(),items,status:o?.status||'AGUARDANDO RECEBIMENTO'};if(!o){db.settings.nextPurchaseNumber=Number(db.settings.nextPurchaseNumber||1)+1;db.purchaseOrders.unshift(obj)}else{const i=db.purchaseOrders.findIndex(x=>x.id===obj.id);db.purchaseOrders[i]=obj}queueSave();closeModal();renderPurchases()}}
function changePurchaseStatus(o){openPurchaseReceipt(o)}
function nextProductCode(){const nums=(db.products||[]).map(p=>String(p.code||'').match(/NI-(\d+)/)).filter(Boolean).map(m=>Number(m[1]));return`NI-${String((Math.max(0,...nums)+1)).padStart(5,'0')}`}
function openPurchaseReceipt(o){if(!o)return;if(['RECEBIDA','FINALIZADA'].includes(o.status))return alert(`Recebimento já confirmado em ${fmtDate(o.receivedDate)}. NF: ${o.invoice||'-'}`);openModal(`<h2>Confirmar recebimento • ${esc(o.number)}</h2><p><strong>${esc(o.supplierName)}</strong> • ${esc(o.supplierCnpj||'')}</p><div class="grid two"><label class="field">Data do recebimento<input id="recDate" type="date" value="${today()}"></label><label class="field">Nº da Nota Fiscal<input id="recNF"></label></div><h3>Conferência e entrada no estoque</h3><p class="muted">A entrada usa Tipo + Produto + Cor + Unidade. Produto existente recebe soma de saldo e custo médio; produto novo recebe SKU automático.</p><div id="recItems"></div><label class="field">Observações / divergências<textarea id="recNotes"></textarea></label><button id="recConfirm" class="btn primary">Confirmar recebimento</button>`);const draw=()=>{$('recItems').innerHTML=(o.items||[]).map((x,i)=>`<div class="grid four purchase-item"><label class="field">Tipo<input value="${esc(canonicalProductType(x.materialType))}" disabled></label><label class="field">Produto<input value="${esc(x.name)} / ${esc(x.color||'SEM COR')}" disabled></label><label class="field">Qtd.<input value="${Number(x.qty||0)} ${esc(x.unit||'UN')}" disabled></label><label class="field">Custo unitário NF<input data-ri-cost="${i}" type="number" step="0.01" value="${Number(x.unitValue||0)}"></label></div>`).join('')};draw();$('recConfirm').onclick=()=>{const nf=$('recNF').value.trim();if(!nf)return alert('Informe o número da Nota Fiscal.');document.querySelectorAll('[data-ri-cost]').forEach(el=>o.items[Number(el.dataset.riCost)].unitValue=Number(el.value||0));for(const it of o.items){const type=canonicalProductType(it.materialType),color=it.color||'SEM COR',unit=it.unit||'UN',qty=Number(it.qty||0),inCost=Number(it.unitValue||0);let p=findProductByIdentity(type,it.name,color,unit);if(p){const oldQty=Number(p.qty||0),oldCost=Number(p.cost||0);p.movements=p.movements||[];p.cost=weightedAverageCost(oldQty,oldCost,qty,inCost);p.qty=oldQty+qty;p.supplierCode=it.supplierCode||p.supplierCode;p.supplierId=o.supplierId;p.supplierName=o.supplierName;ensureProductCode(p);p.movements.push({id:uid(),date:$('recDate').value,type:'ENTRADA POR COMPRA',qty,balance:p.qty,unit:p.unit,by:currentUsername(),reason:`${o.number} • NF ${nf} • custo ${money(inCost)}`})}else{p={id:uid(),code:nextProductCode(),supplierCode:it.supplierCode||'',type,category:'COMPRAS',name:String(it.name||'').trim(),color,qty,cost:inCost,markup:80,unit,minimumStock:0,stockManaged:true,supplierId:o.supplierId,supplierName:o.supplierName,movements:[{id:uid(),date:$('recDate').value,type:'ENTRADA POR COMPRA',qty,balance:qty,unit,by:currentUsername(),reason:`${o.number} • NF ${nf}`}],createdAt:new Date().toISOString()};db.products.unshift(p)}}o.receivedDate=$('recDate').value;o.invoice=nf;o.receiptCheck=$('recNotes').value.trim();o.status='RECEBIDA';o.total=(o.items||[]).reduce((a,x)=>a+Number(x.qty||0)*Number(x.unitValue||0),0);queueSave();closeModal();setupSelectors();renderAll();setTimeout(()=>openPurchaseValues(o),100)}}
function openPurchaseValues(o){if(!o||!['RECEBIDA','FINALIZADA'].includes(o.status))return alert('Confirme o recebimento e a Nota Fiscal antes de inserir as duplicatas.');let rows=clone(o.duplicates||[]);if(!rows.length)rows=[{documentNumber:o.invoice||'',dueDate:'',value:o.total||0}];openModal(`<h2>Valores / duplicatas • ${esc(o.number)}</h2><p><strong>Fornecedor:</strong> ${esc(o.supplierName)} &nbsp; <strong>NF:</strong> ${esc(o.invoice||'-')} &nbsp; <strong>Total da NF:</strong> ${money(o.total||0)}</p><div id="dupCheck" class="kpis"></div><div id="dupRows"></div><button id="dupAdd" class="btn secondary">+ Duplicata</button> <button id="dupSave" class="btn primary">Salvar e enviar ao Contas a Pagar</button>`);const update=()=>{const total=rows.reduce((a,x)=>a+Number(x.value||0),0),diff=Number(o.total||0)-total;$('dupCheck').innerHTML=`<div class="kpi"><span>Total da NF</span><strong>${money(o.total||0)}</strong></div><div class="kpi"><span>Distribuído nas duplicatas</span><strong>${money(total)}</strong></div><div class="kpi"><span>Diferença</span><strong>${money(diff)}</strong></div>`};const draw=()=>{$('dupRows').innerHTML=rows.map((x,i)=>`<div class="grid three purchase-item"><label class="field">Nº documento<input data-ddoc="${i}" value="${esc(x.documentNumber||'')}"></label><label class="field">Vencimento<input data-ddue="${i}" type="date" value="${x.dueDate||''}"></label><label class="field">Valor<input data-dval="${i}" type="number" step="0.01" value="${Number(x.value||0)}"></label></div>`).join('');document.querySelectorAll('[data-ddoc]').forEach(el=>el.oninput=()=>rows[el.dataset.ddoc].documentNumber=el.value);document.querySelectorAll('[data-ddue]').forEach(el=>el.oninput=()=>rows[el.dataset.ddue].dueDate=el.value);document.querySelectorAll('[data-dval]').forEach(el=>el.oninput=()=>{rows[el.dataset.dval].value=Number(el.value);update()});update()};draw();$('dupAdd').onclick=()=>{rows.push({documentNumber:o.invoice||'',dueDate:'',value:0});draw()};$('dupSave').onclick=()=>{if(rows.some(x=>!x.documentNumber||!x.dueDate||Number(x.value)<=0))return alert('Preencha documento, vencimento e valor de todas as duplicatas.');const sum=rows.reduce((a,x)=>a+Number(x.value||0),0);if(Math.abs(sum-Number(o.total||0))>0.01)return alert(`A soma das duplicatas (${money(sum)}) precisa ser igual ao total da NF (${money(o.total||0)}).`);o.duplicates=rows;o.paymentDataEntered=true;o.status='FINALIZADA';db.payables=(db.payables||[]).filter(p=>p.purchaseOrderId!==o.id);rows.forEach((x,i)=>db.payables.unshift({id:uid(),title:x.documentNumber,documentNumber:x.documentNumber,definition:`COMPRA • ${o.supplierName}`,purchaseOrder:o.number,purchaseOrderId:o.id,quoteNumber:o.number,dueDate:x.dueDate,value:Number(x.value),paidValue:0,paidDate:'',notes:`NF ${o.invoice} • parcela ${i+1}/${rows.length}`}));queueSave();closeModal();renderAll()}}
function printPurchase(o){const rows=(o.items||[]).map(x=>`<tr><td>${esc(x.materialType||'-')}</td><td>${esc(x.name)}</td><td>${esc(x.supplierCode||'-')}</td><td>${x.qty}</td></tr>`).join('');printWindow(`<h2>ORDEM DE COMPRA ${esc(o.number)}</h2><p><strong>Fornecedor:</strong> ${esc(o.supplierName)} • <strong>CNPJ:</strong> ${esc(o.supplierCnpj||'-')}<br><strong>Contato:</strong> ${esc(o.supplierContact||'-')} • <strong>Data:</strong> ${fmtDate(o.date)}<br><strong>Responsável:</strong> ${esc(o.responsible||'-')} • <strong>Solicitante:</strong> ${esc(o.requester||'-')}</p><table><tr><th>Tipo de material</th><th>Detalhamento</th><th>Cód. fornecedor</th><th>Qtd.</th></tr>${rows}</table><p>${esc(o.notes||'')}</p>`)}
function printWindow(body){const w=window.open('about:blank','_blank');if(!w)return alert('O navegador bloqueou a abertura do PDF. Libere pop-ups para este site.');w.document.write(`<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova Imagem ERP V10</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:8mm;color:#173638;font-size:10pt}h2{font-size:16pt;margin:0;color:#075b5b}.pdf-head{display:grid;grid-template-columns:6cm 1fr;gap:12px;align-items:start}.pdf-head img{width:6cm;height:4cm;object-fit:contain;object-position:left top}.store-client{font-size:12pt;line-height:1.35}.quote-number{font-size:12pt;font-weight:700;margin:6px 0 12px}.env-block{margin:0 0 12px;break-inside:avoid}.env-title{font-size:11pt;font-weight:700;padding:6px 8px;background:#eef6f5;border:1px solid #b9d1cf}.env-table,.summary-table{width:100%;border-collapse:collapse}.env-table th,.env-table td,.summary-table th,.summary-table td{border:1px solid #c7d8d6;padding:6px;font-size:10pt;text-align:left;vertical-align:top}.env-table th{width:17%;background:#f7faf9}.section-title{font-size:11pt;font-weight:700;color:#075b5b;margin:14px 0 6px}.totals{font-size:11pt;font-weight:700}.conditions{font-size:10pt;line-height:1.45}.sign{margin-top:16px}@page{size:A4 portrait;margin:8mm}@media print{body{margin:0}.screen-only{display:none!important}}</style></head><body>${body}<script>window.addEventListener('afterprint',()=>{});<\/script></body></html>`);w.document.close();setTimeout(()=>{try{w.focus();w.print()}catch(e){}},450)}
function detailRows(c,e){const r=[];if(c.finishCalc)r.push([e.finish+' '+e.finishColor,c.finishCalc.consumption.toFixed(2)+' m',c.finishCalc.unitPrice,c.finishCalc.cost]);if(c.liningCalc)r.push([e.lining+' '+e.liningColor,c.liningCalc.consumption.toFixed(2)+' m',c.liningCalc.unitPrice,c.liningCalc.cost]);if(c.finishCalc&&e.finishPleat==='WAVE')r.push(['FITA WAVE COM BOTÕES INOX',c.finishCalc.consumption.toFixed(2)+' m',Number(db.priceConfig.pleatLabor.WAVE||0),c.finishPleat]);r.push(['DESLIZANTES',c.finishSliders+c.liningSliders+' un',c.sliderCost/Math.max(1,c.finishSliders+c.liningSliders),c.sliderCost]);if(e.finishPleat==='WAVE'||e.liningPleat==='WAVE')r.push(['CORDÃO WAVE',e.width/100+' m',0,0]);r.push([e.fixation+' '+e.fixColor,c.fixationCalc.meters?.toFixed(2)+' m',c.fixationCalc.total/Math.max(1,c.fixationCalc.meters||1),c.fixationCalc.total]);r.push(['ACABAMENTO / CONFECÇÃO',c.sewingMeters.toFixed(2)+' m',Number(db.priceConfig.sewingPerMeter||0),c.sewingCost+c.finishPleat+c.liningPleat]);r.push(['MÃO DE OBRA / INSTALAÇÃO','1',c.installCost,c.installCost]);return r}
function printQuote(q,type='summary'){
 const t=quoteTotals(q);let body=`<div class="pdf-head"><img src="${location.origin}/icon-512.png"><div class="store-client"><strong>Nova Imagem Cortinas & Persianas</strong><br><span>ORÇAMENTO COMERCIAL</span><br><br><strong>Cliente:</strong> ${esc(q.client||'-')}<br><strong>Contato:</strong> ${esc(q.contact||'-')}<br><strong>Endereço:</strong> ${esc(q.address||'-')}<br><strong>Vendedor:</strong> ${esc(displaySeller(q))}<br><strong>Data:</strong> ${fmtDate(q.date)}</div></div><div class="quote-number">ORÇAMENTO Nº ${String(q.numero).padStart(6,'0')}</div>`;
 for(const e of q.environments||[]){const c=calcEnvironment(e);if(!c)continue;body+=`<div class="env-block"><div class="env-title">${esc(e.name)}</div><table class="env-table"><tr><th>Medidas</th><td>${e.width} × ${e.height} cm</td><th>Aberturas</th><td>${Math.max(0,Number(e.leaves||1)-1)}</td></tr><tr><th>Acabamento</th><td>${c.finishCalc?esc(`${e.finish} / ${e.finishColor} / ${e.finishPleat} ${e.finishGather}:1`):'—'}</td><th>Forro</th><td>${c.liningCalc?esc(`${e.lining} / ${e.liningColor} / ${e.liningPleat} ${e.liningGather}:1`):'—'}</td></tr><tr><th>Fixação</th><td colspan="3">${esc(e.fixation||'-')} • ${esc(e.fixColor||'')}</td></tr><tr><th>18x</th><td>${money(c.p18)}</td><th>4x</th><td>${money(c.base4)}</td></tr><tr><th>À vista</th><td colspan="3"><strong>${money(c.cash)}</strong></td></tr>${e.notes?`<tr><th>Observações</th><td colspan="3">${esc(e.notes)}</td></tr>`:''}</table></div>`}
 if((q.blinds||[]).length){body+=`<div class="section-title">Persianas</div>`;for(const x of q.blinds){const qty=Number(x.qty||1);body+=`<div class="env-block"><div class="env-title">${esc(x.environment||'PERSIANA')}</div><table class="env-table"><tr><th>Modelo</th><td>${esc(x.model||'-')}</td><th>Cor</th><td>${esc(x.color||'-')}</td></tr><tr><th>Medidas</th><td>${x.width} × ${x.height} cm</td><th>Quantidade</th><td>${qty} un.</td></tr><tr><th>Comando</th><td>${esc(x.commandSide||'-')}</td><th>Bandô</th><td>${esc(x.bando||'-')}</td></tr><tr><th>18x</th><td>${money(Number(x.p18||0)*qty)}</td><th>4x</th><td>${money(Number(x.p4||0)*qty)}</td></tr><tr><th>À vista</th><td colspan="3"><strong>${money(Number(x.cash||0)*qty)}</strong></td></tr></table></div>`}}
 if((q.looseProducts||[]).length){for(const [title,list] of [['Produtos Avulsos',(q.looseProducts||[]).filter(a=>a.stockManaged!==false)],['Produtos Fora de Estoque',(q.looseProducts||[]).filter(a=>a.stockManaged===false)]]){if(!list.length)continue;body+=`<div class="section-title">${title}</div><table class="summary-table"><tr><th>Descrição</th><th>Produto</th><th>Qtd.</th><th>18x</th><th>4x</th><th>À vista</th></tr>${list.map(a=>`<tr><td>${esc(a.description||a.name)}</td><td>${esc(a.name)} / ${esc(a.color||'')}</td><td>${a.qty} ${esc(a.unit||'')}</td><td>${money(Number(a.p18||0)*Number(a.qty||1))}</td><td>${money(Number(a.p4||0)*Number(a.qty||1))}</td><td>${money(Number(a.cash||0)*Number(a.qty||1))}</td></tr>`).join('')}</table>`}}
 if(Number(q.travel||0)>0)body+=`<p><strong>Deslocamento:</strong> ${money(q.travel)}</p>`;
 body+=`<div class="section-title">Resumo</div><table class="summary-table"><tr><th>Condição</th><th>Valor final</th></tr><tr><td>18x</td><td class="totals">${money(t.p18)}</td></tr><tr><td>Até 4x</td><td class="totals">${money(t.p4)}</td></tr><tr><td>À vista</td><td class="totals">${money(t.cash)}</td></tr></table>${q.discountPercent?`<p><strong>Desconto:</strong> ${q.discountPercent}% • ${esc(q.discountReason||'')}</p>`:''}<div class="section-title">Condições comerciais</div><div class="conditions">Validade do orçamento: 5 dias. Medidas, tecidos, cores e fixações devem ser conferidos antes da ordem de produção. Prazo padrão: até 30 dias úteis após emissão do pedido.</div><p class="sign"><strong>Atenciosamente, ${esc(displaySeller(q))}</strong></p>`;printWindow(body)
}


function hrData(){db.settings=db.settings||{};db.settings.hr=db.settings.hr||{employees:[],providers:[],payrollClosings:[]};db.settings.hr.employees=db.settings.hr.employees||[];db.settings.hr.providers=db.settings.hr.providers||[];db.settings.hr.payrollClosings=db.settings.hr.payrollClosings||[];return db.settings.hr}
function renderHR(){const h=hrData(),et=$('employeeTable'),pt=$('providerTable');if(!et||!pt)return;et.innerHTML=h.employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.role||'-')}</td><td>${fmtDate(e.admissionDate)}</td><td>${money(e.salary)}</td><td><span class="badge ${e.active===false?'danger':'ok'}">${e.active===false?'INATIVO':'ATIVO'}</span></td><td><button class="btn ghost" data-emp-edit="${e.id}">Editar</button></td></tr>`).join('');pt.innerHTML=h.providers.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.personType||'-')}</td><td>${esc(e.service||'-')}</td><td>${money(e.value)}</td><td><span class="badge ${e.active===false?'danger':'ok'}">${e.active===false?'INATIVO':'ATIVO'}</span></td><td><button class="btn ghost" data-prov-edit="${e.id}">Editar</button></td></tr>`).join('');const activeEmp=h.employees.filter(x=>x.active!==false),activeProv=h.providers.filter(x=>x.active!==false);if($('hrSummary'))$('hrSummary').innerHTML=[['Colaboradores ativos',activeEmp.length],['Prestadores ativos',activeProv.length],['Folha-base',money(activeEmp.reduce((a,x)=>a+Number(x.salary||0),0))],['Serviços recorrentes',money(activeProv.reduce((a,x)=>a+Number(x.value||0),0))]].map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');document.querySelectorAll('[data-emp-edit]').forEach(b=>b.onclick=()=>openEmployee(h.employees.find(x=>x.id===b.dataset.empEdit)));document.querySelectorAll('[data-prov-edit]').forEach(b=>b.onclick=()=>openProvider(h.providers.find(x=>x.id===b.dataset.provEdit)))}
function openEmployee(e=null){openModal(`<h2>${e?'Editar':'Novo'} colaborador CLT</h2><div class="grid two"><label class="field">Nome completo<input id="hrName" value="${esc(e?.name||'')}"></label><label class="field">CPF<input id="hrCpf" value="${esc(e?.cpf||'')}"></label><label class="field">RG<input id="hrRg" value="${esc(e?.rg||'')}"></label><label class="field">Cargo<input id="hrRole" value="${esc(e?.role||'')}"></label><label class="field">Setor<input id="hrSector" value="${esc(e?.sector||'')}"></label><label class="field">Admissão<input id="hrAdm" type="date" value="${e?.admissionDate||''}"></label><label class="field">Salário-base<input id="hrSalary" type="number" step="0.01" value="${Number(e?.salary||0)}"></label><label class="field">Usuário vendedor vinculado<select id="hrUser"><option value="">SEM VÍNCULO</option>${allUsers().map(u=>`<option value="${u.username}" ${norm(e?.username)===norm(u.username)?'selected':''}>${esc(u.name||u.username)}</option>`).join('')}</select></label><label class="field">Status<select id="hrActive"><option value="1">ATIVO</option><option value="0" ${e?.active===false?'selected':''}>INATIVO</option></select></label><label class="field">Jornada / observações<input id="hrJourney" value="${esc(e?.journey||'')}"></label><label class="field" style="grid-column:1/-1">Documentos, exames, certificados e cursos<textarea id="hrDocs" rows="5" placeholder="Registre nome do documento, data, validade e observações. Para anexos binários, faremos a etapa de armazenamento dedicado.">${esc(e?.documents||'')}</textarea></label></div><button id="hrSave" class="btn primary">Salvar</button>`);$('hrSave').onclick=()=>{const h=hrData(),obj={...(e||{}),id:e?.id||uid(),name:$('hrName').value.trim(),cpf:$('hrCpf').value.trim(),rg:$('hrRg').value.trim(),role:$('hrRole').value.trim(),sector:$('hrSector').value.trim(),admissionDate:$('hrAdm').value,salary:Number($('hrSalary').value||0),username:$('hrUser').value,active:$('hrActive').value==='1',journey:$('hrJourney').value.trim(),documents:$('hrDocs').value.trim(),updatedAt:new Date().toISOString()};if(!obj.name)return alert('Informe o nome.');const i=h.employees.findIndex(x=>x.id===obj.id);if(i>=0)h.employees[i]=obj;else h.employees.unshift(obj);queueSave();closeModal();renderHR()}}
function openProvider(e=null){openModal(`<h2>${e?'Editar':'Novo'} prestador de serviços</h2><div class="grid two"><label class="field">PF/PJ<select id="pvType"><option>PF</option><option ${e?.personType==='PJ'?'selected':''}>PJ</option></select></label><label class="field">Nome / Razão social<input id="pvName" value="${esc(e?.name||'')}"></label><label class="field">CPF/CNPJ<input id="pvDoc" value="${esc(e?.document||'')}"></label><label class="field">Natureza do serviço<input id="pvService" value="${esc(e?.service||'')}"></label><label class="field">Valor recorrente / referência<input id="pvValue" type="number" step="0.01" value="${Number(e?.value||0)}"></label><label class="field">Periodicidade<select id="pvPeriod"><option>MENSAL</option><option>POR SERVIÇO</option><option>OUTRO</option></select></label><label class="field">Início contrato<input id="pvStart" type="date" value="${e?.contractStart||''}"></label><label class="field">Fim contrato<input id="pvEnd" type="date" value="${e?.contractEnd||''}"></label><label class="field">Status<select id="pvActive"><option value="1">ATIVO</option><option value="0" ${e?.active===false?'selected':''}>INATIVO</option></select></label><label class="field">Contrato / observações<textarea id="pvContract">${esc(e?.contract||'')}</textarea></label></div><button id="pvSave" class="btn primary">Salvar</button>`);if(e?.periodicity)$('pvPeriod').value=e.periodicity;$('pvSave').onclick=()=>{const h=hrData(),obj={...(e||{}),id:e?.id||uid(),personType:$('pvType').value,name:$('pvName').value.trim(),document:$('pvDoc').value.trim(),service:$('pvService').value.trim(),value:Number($('pvValue').value||0),periodicity:$('pvPeriod').value,contractStart:$('pvStart').value,contractEnd:$('pvEnd').value,active:$('pvActive').value==='1',contract:$('pvContract').value.trim(),updatedAt:new Date().toISOString()};if(!obj.name)return alert('Informe o prestador.');const i=h.providers.findIndex(x=>x.id===obj.id);if(i>=0)h.providers[i]=obj;else h.providers.unshift(obj);queueSave();closeModal();renderHR()}}
function payrollRows(competence){const h=hrData(),rows=[];for(const e of h.employees.filter(x=>x.active!==false)){const username=norm(e.username),commission=username?db.orders.filter(o=>resolveSellerUser(o)===username&&String(o.createdDate||'').slice(0,7)===competence).reduce((a,o)=>a+Number(o.agreedValue||0)*sellerCommission(username)/100,0):0;rows.push({kind:'CLT',refId:e.id,name:e.name,username,base:Number(e.salary||0),commission,total:Number(e.salary||0)+commission})}for(const p of h.providers.filter(x=>x.active!==false&&x.periodicity==='MENSAL'))rows.push({kind:'PRESTADOR',refId:p.id,name:p.name,base:Number(p.value||0),commission:0,total:Number(p.value||0)});return rows}
function previewPayroll(){const comp=$('hrCompetence')?.value;if(!comp)return alert('Informe a competência.');const rows=payrollRows(comp);$('payrollPreview').innerHTML=`<table class="table"><thead><tr><th>Pessoa</th><th>Tipo</th><th>Base</th><th>Comissão</th><th>Total</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.kind}</td><td>${money(r.base)}</td><td>${money(r.commission)}</td><td><strong>${money(r.total)}</strong></td></tr>`).join('')}</tbody></table>`;return rows}
function closePayroll(){const comp=$('hrCompetence')?.value,due=$('hrDueDate')?.value;if(!comp||!due)return alert('Informe competência e vencimento.');const h=hrData();if(h.payrollClosings.some(x=>x.competence===comp))return alert('Esta competência já foi fechada. Evitamos duplicidade.');const rows=payrollRows(comp);if(!rows.length)return alert('Não há remunerações para fechar.');for(const r of rows){db.payables.unshift({id:uid(),title:`DP-${comp}-${r.refId}`,documentNumber:`DP-${comp}-${r.refId}`,definition:r.kind==='CLT'?`REMUNERAÇÃO • ${r.name}`:`SERVIÇOS • ${r.name}`,quoteNumber:comp,dueDate:due,value:r.total,paidValue:0,paidDate:'',notes:r.commission?`Salário/base ${money(r.base)} + comissão ${money(r.commission)}`:`Competência ${comp}`,hrCompetence:comp,hrRefId:r.refId})}h.payrollClosings.push({id:uid(),competence:comp,dueDate:due,rows,closedAt:new Date().toISOString(),by:currentUsername()});queueSave();renderPayables();renderHR();alert('Competência fechada e enviada ao Contas a Pagar.')}

function bind(){
  const onClick=(id,fn)=>{const el=$(id);if(el)el.onclick=fn};
  const on=(id,event,fn)=>{const el=$(id);if(el)el.addEventListener(event,fn)};

  document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{
    const model=$('eModel');
    if(model)model.value=b.dataset.model;
    updateModelFields();
  });

  ['eName','eWidth','eHeight','eLeaves','eFinish','eFinishColor','eFinishPleat','eFinishGather','eLining','eLiningColor','eLiningPleat','eLiningGather','eFixation','eFixColor','eCustomPleat']
    .forEach(id=>on(id,'input',updatePreview));

  on('eFinish','change',()=>{refreshFinishColors();updatePreview()});
  on('eLining','change',()=>{refreshLiningColors();updatePreview()});
  on('eFixation','change',()=>{refreshFixColors();updatePreview()});

  onClick('addEnvBtn',()=>{
    const e=envFromForm();
    if(!e.name||!e.width||!e.height)return alert('Preencha ambiente, largura e altura.');
    draft.environments.push(e);
    renderQuote();
    clearEnv();
  });

  ['qClient','qDate','qAddress','qContact','qSeller'].forEach(id=>on(id,'input',syncDraft));
  on('qTravel','input',()=>{syncDraft();renderQuote()});
  ['qDiscount','qDiscountReason'].forEach(id=>on(id,'input',()=>{syncDraft();renderQuote()}));

  onClick('addLooseBtn',openLooseProduct);
  onClick('addSpecialBtn',openSpecialProduct);
  onClick('addBlindBtn',openBlind);
  onClick('saveQuoteBtn',()=>saveQuote(false));
  onClick('savePrintBtn',()=>saveQuote(true));
  onClick('resetQuoteBtn',resetQuote);

  on('quoteSearch','input',renderQuotes);
  on('clientSearch','input',renderClients);
  on('productSearch','input',renderProducts);

  onClick('newClientBtn',()=>openClientModal());
  onClick('newProductBtn',()=>alert('Cadastro de novo produto oficial será habilitado na próxima etapa do backend.'));
  onClick('inventoryCountBtn',()=>alert('Inventário físico dos 183 produtos oficiais será migrado na próxima etapa.'));
   onClick('combineProductsBtn',openCombineProducts);
   onClick('homeLogo',goHome);
  onClick('savePricesBtn',savePricing);
  onClick('newPayableBtn',()=>openPayable());
  onClick('newSupplierBtn',()=>openSupplier());
  onClick('newPurchaseBtn',()=>openPurchase());

  ['payFrom','payTo','payStatus'].forEach(id=>on(id,'input',renderPayables));
  onClick('clearPayFilters',()=>{
    if($('payFrom'))$('payFrom').value='';
    if($('payTo'))$('payTo').value='';
    if($('payStatus'))$('payStatus').value='';
    renderPayables();
  });
  onClick('printPayablesBtn',()=>{
    const rows=[...document.querySelectorAll('#payablesTable tr')]
      .map(tr=>'<tr>'+tr.innerHTML.replace(/<td><button[\s\S]*?<\/td>/,'')+'</tr>').join('');
    printWindow(`<h2>CONTAS A PAGAR</h2>${$('payableSummary')?.innerHTML||''}<table>${rows}</table>`);
  });

  onClick('newReworkBtn',openRework);
  onClick('newUserBtn',openUser);

  ['kpiFrom','kpiTo','kpiSeller'].forEach(id=>on(id,'input',renderKpis));
  onClick('clearKpiFilters',()=>{
    if($('kpiFrom'))$('kpiFrom').value='';
    if($('kpiTo'))$('kpiTo').value='';
    if($('kpiSeller'))$('kpiSeller').value='';
    renderKpis();
  });
  onClick('printKpisBtn',printKpis);

  onClick('newEmployeeBtn',()=>openEmployee());
  onClick('newProviderBtn',()=>openProvider());
  onClick('previewPayrollBtn',previewPayroll);
  onClick('closePayrollBtn',closePayroll);

  onClick('modalClose',closeModal);
  on('modal','click',e=>{if(e.target===$('modal'))closeModal()});

  onClick('loginBtn',doLogin);
  on('loginPass','keydown',e=>{if(e.key==='Enter')doLogin()});
  onClick('logoutBtn',logout);
}
async function init(){
  bind();
  db.priceConfig=mergeConfig(db.priceConfig);
  if(await restore())return;
  const loginScreen=$('loginScreen');
  if(loginScreen)loginScreen.classList.remove('hidden');
  setTimeout(()=>$('loginUser')?.focus(),50);
}
init();
